use chrono::{DateTime, TimeDelta, Utc};
use std::cmp::Ordering;
use std::collections::BTreeMap;
use std::fmt;

#[derive(Clone)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    DateTime(DateTime<Utc>),
    Duration(TimeDelta),
    Obj(BTreeMap<String, Value>),
    Array(Vec<Value>),
    None,
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b || (a.is_nan() && b.is_nan()),
            (Value::Int(a), Value::Float(b)) => (*a as f64) == *b,
            (Value::Float(a), Value::Int(b)) => *a == (*b as f64),
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::DateTime(a), Value::DateTime(b)) => a == b,
            (Value::Duration(a), Value::Duration(b)) => a == b,
            (Value::Obj(a), Value::Obj(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => a == b,
            (Value::None, Value::None) => true,
            _ => false,
        }
    }
}

impl Eq for Value {}

impl std::hash::Hash for Value {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        match self {
            Value::Str(s) => {
                0u8.hash(state);
                s.hash(state)
            }
            Value::Int(i) => {
                1u8.hash(state);
                (*i as f64).to_bits().hash(state)
            }
            Value::Float(f) => {
                1u8.hash(state);
                f.to_bits().hash(state)
            }
            Value::Bool(b) => {
                2u8.hash(state);
                b.hash(state)
            }
            Value::DateTime(d) => {
                3u8.hash(state);
                d.hash(state)
            }
            Value::Duration(d) => {
                4u8.hash(state);
                d.hash(state)
            }
            Value::Obj(o) => {
                5u8.hash(state);
                for (k, v) in o {
                    k.hash(state);
                    v.hash(state);
                }
            }
            Value::Array(a) => {
                6u8.hash(state);
                for v in a {
                    v.hash(state);
                }
            }
            Value::None => 7u8.hash(state),
        }
    }
}

fn rank(v: &Value) -> u8 {
    match v {
        Value::None => 0,
        Value::Bool(_) => 1,
        Value::Int(_) | Value::Float(_) => 2,
        Value::Str(_) => 3,
        Value::DateTime(_) => 4,
        Value::Duration(_) => 5,
        Value::Array(_) => 6,
        Value::Obj(_) => 7,
    }
}

impl Value {
    /// Partial comparison used for `<`, `>` etc.
    pub fn partial_compare(&self, other: &Value) -> Option<Ordering> {
        match (self, other) {
            (Value::Int(a), Value::Int(b)) => Some(a.cmp(b)),
            (Value::Int(a), Value::Float(b)) => (*a as f64).partial_cmp(b),
            (Value::Float(a), Value::Int(b)) => a.partial_cmp(&(*b as f64)),
            (Value::Float(a), Value::Float(b)) => a.partial_cmp(b),
            (Value::Str(a), Value::Str(b)) => Some(a.cmp(b)),
            (Value::Bool(a), Value::Bool(b)) => Some(a.cmp(b)),
            (Value::DateTime(a), Value::DateTime(b)) => Some(a.cmp(b)),
            (Value::Duration(a), Value::Duration(b)) => Some(a.cmp(b)),
            (Value::Obj(a), Value::Obj(b)) => {
                let mut ia = a.iter();
                let mut ib = b.iter();
                loop {
                    match (ia.next(), ib.next()) {
                        (None, None) => return Some(Ordering::Equal),
                        (None, Some(_)) => return Some(Ordering::Less),
                        (Some(_), None) => return Some(Ordering::Greater),
                        (Some((ka, va)), Some((kb, vb))) => {
                            match ka.cmp(kb) {
                                Ordering::Equal => {}
                                o => return Some(o),
                            }
                            match va.partial_compare(vb) {
                                Some(Ordering::Equal) => {}
                                o => return o,
                            }
                        }
                    }
                }
            }
            (Value::Array(_), Value::Array(_)) => None,
            (Value::None, Value::None) => Some(Ordering::Equal),
            _ => Some(rank(self).cmp(&rank(other))),
        }
    }

    /// Total order used for sorting.
    pub fn total_cmp(&self, other: &Value) -> Ordering {
        match (self, other) {
            (Value::Float(a), Value::Float(b)) => a.partial_cmp(b).unwrap_or_else(|| {
                a.is_nan().cmp(&b.is_nan())
            }),
            (Value::Int(a), Value::Float(b)) => (*a as f64).partial_cmp(b).unwrap_or(Ordering::Less),
            (Value::Float(a), Value::Int(b)) => a.partial_cmp(&(*b as f64)).unwrap_or(Ordering::Greater),
            (Value::Obj(a), Value::Obj(b)) => {
                let mut ia = a.iter();
                let mut ib = b.iter();
                loop {
                    match (ia.next(), ib.next()) {
                        (None, None) => return Ordering::Equal,
                        (None, Some(_)) => return Ordering::Less,
                        (Some(_), None) => return Ordering::Greater,
                        (Some((ka, va)), Some((kb, vb))) => {
                            match ka.cmp(kb) {
                                Ordering::Equal => {}
                                o => return o,
                            }
                            match va.total_cmp(vb) {
                                Ordering::Equal => {}
                                o => return o,
                            }
                        }
                    }
                }
            }
            _ => self.partial_compare(other).unwrap_or(Ordering::Equal),
        }
    }

    pub fn from_float(f: f64) -> Value {
        if (f - f.floor()) < f64::EPSILON {
            Value::Int(f as i64)
        } else {
            Value::Float(f)
        }
    }

    pub fn from_bool(b: bool) -> Value {
        Value::Bool(b)
    }

    /// Infer a typed value from a string.
    pub fn from_string(s: &str) -> Value {
        let t = s.trim();
        if let Ok(i) = t.parse::<i64>() {
            return Value::Int(i);
        }
        if let Ok(f) = t.parse::<f64>() {
            return Value::from_float(f);
        }
        match t {
            "true" => Value::Bool(true),
            "false" => Value::Bool(false),
            _ => Value::Str(t.to_string()),
        }
    }

    pub fn from_json(v: &serde_json::Value) -> Value {
        match v {
            serde_json::Value::Null => Value::None,
            serde_json::Value::Bool(b) => Value::Bool(*b),
            serde_json::Value::Number(n) => {
                if let Some(i) = n.as_i64() {
                    Value::Int(i)
                } else if let Some(f) = n.as_f64() {
                    Value::from_float(f)
                } else {
                    Value::None
                }
            }
            serde_json::Value::String(s) => Value::Str(s.clone()),
            serde_json::Value::Array(a) => Value::Array(a.iter().map(Value::from_json).collect()),
            serde_json::Value::Object(o) => {
                let mut m = BTreeMap::new();
                for (k, v) in o {
                    m.insert(k.clone(), Value::from_json(v));
                }
                Value::Obj(m)
            }
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        match self {
            Value::Str(s) => serde_json::Value::String(s.clone()),
            Value::Int(i) => serde_json::Value::Number((*i).into()),
            Value::Float(f) => match serde_json::Number::from_f64(*f) {
                Some(n) => serde_json::Value::Number(n),
                None => serde_json::Value::Null,
            },
            Value::Bool(b) => serde_json::Value::Bool(*b),
            Value::DateTime(d) => serde_json::Value::String(d.to_rfc3339()),
            Value::Duration(d) => serde_json::Value::String(d.to_string()),
            Value::Obj(o) => {
                let mut m = serde_json::Map::new();
                for (k, v) in o {
                    m.insert(k.clone(), v.to_json());
                }
                serde_json::Value::Object(m)
            }
            Value::Array(a) => serde_json::Value::Array(a.iter().map(|v| v.to_json()).collect()),
            Value::None => serde_json::Value::Null,
        }
    }

    /// Numeric view used for arithmetic.
    pub fn as_number(&self) -> Option<Num> {
        match self {
            Value::Int(i) => Some(Num::Int(*i)),
            Value::Float(f) => Some(Num::Float(*f)),
            Value::Str(s) => match Value::from_string(s) {
                Value::Int(i) => Some(Num::Int(i)),
                Value::Float(f) => Some(Num::Float(f)),
                _ => None,
            },
            _ => None,
        }
    }

    /// String conversion used for functions such as concat (scalars use Display,
    /// compound values use Debug).
    pub fn to_func_string(&self) -> String {
        match self {
            Value::Str(s) => s.clone(),
            Value::Int(i) => i.to_string(),
            Value::Float(f) => f.to_string(),
            Value::Bool(b) => b.to_string(),
            Value::None => "None".to_string(),
            Value::DateTime(d) => format!("{:?}", d),
            Value::Duration(d) => format!("{:?}", d),
            Value::Array(a) => {
                let parts: Vec<String> = a.iter().map(|v| format!("{:?}", v)).collect();
                format!("[{}]", parts.join(", "))
            }
            Value::Obj(o) => debug_obj(o),
        }
    }

    pub fn is_none(&self) -> bool {
        matches!(self, Value::None)
    }
}

fn debug_obj(o: &BTreeMap<String, Value>) -> String {
    let parts: Vec<String> = o.iter().map(|(k, v)| format!("{:?}: {:?}", k, v)).collect();
    format!("{{{}}}", parts.join(", "))
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Value::Str(s) => write!(f, "Str({:?})", s),
            Value::Int(i) => write!(f, "Int({})", i),
            Value::Float(x) => write!(f, "Float({:?})", x),
            Value::Bool(b) => write!(f, "Bool({})", b),
            Value::DateTime(d) => write!(f, "DateTime({:?})", d),
            Value::Duration(d) => write!(f, "Duration({:?})", d),
            Value::Obj(o) => write!(f, "Obj({})", debug_obj(o)),
            Value::Array(a) => {
                let parts: Vec<String> = a.iter().map(|v| format!("{:?}", v)).collect();
                write!(f, "Array([{}])", parts.join(", "))
            }
            Value::None => write!(f, "None"),
        }
    }
}

pub fn format_duration(d: &TimeDelta) -> String {
    let total: i128 = d.num_seconds() as i128 * 1_000_000_000i128 + d.subsec_nanos() as i128;
    let mut rem = total;
    let units: [(i128, &str); 7] = [
        (604_800_000_000_000, "w"),
        (86_400_000_000_000, "d"),
        (3_600_000_000_000, "h"),
        (60_000_000_000, "m"),
        (1_000_000_000, "s"),
        (1_000_000, "ms"),
        (1_000, "us"),
    ];
    let mut out = String::new();
    for (size, name) in units.iter() {
        let n = rem / size;
        rem -= n * size;
        if n != 0 {
            out.push_str(&format!("{}{}", n, name));
        }
    }
    out
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Value::Str(s) => write!(f, "{}", s),
            Value::Int(i) => write!(f, "{}", i),
            Value::Float(x) => write!(f, "{:.2}", x),
            Value::Bool(b) => write!(f, "{}", b),
            Value::DateTime(d) => write!(f, "{}", d),
            Value::Duration(d) => write!(f, "{}", format_duration(d)),
            Value::Obj(o) => {
                write!(f, "{{")?;
                let mut first = true;
                for (k, v) in o {
                    if !first {
                        write!(f, ", ")?;
                    }
                    first = false;
                    write!(f, "{}:{}", k, v)?;
                }
                write!(f, "}}")
            }
            Value::Array(a) => {
                write!(f, "[")?;
                let mut first = true;
                for v in a {
                    if !first {
                        write!(f, ", ")?;
                    }
                    first = false;
                    write!(f, "{}", v)?;
                }
                write!(f, "]")
            }
            Value::None => write!(f, "None"),
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Num {
    Int(i64),
    Float(f64),
}

impl Num {
    pub fn as_f64(&self) -> f64 {
        match self {
            Num::Int(i) => *i as f64,
            Num::Float(f) => *f,
        }
    }
    pub fn to_value(&self) -> Value {
        match self {
            Num::Int(i) => Value::Int(*i),
            Num::Float(f) => Value::from_float(*f),
        }
    }
}
