// Rendering of annotated error messages in the style used by the original tool.

#[derive(Clone, Debug)]
pub struct Annot {
    pub start: usize,
    pub end: usize,
    pub label: String,
    pub primary: bool,
}

#[derive(Clone, Debug)]
pub struct Diag {
    pub level: &'static str,
    pub title: String,
    pub annots: Vec<Annot>,
    pub helps: Vec<String>,
}

impl Diag {
    pub fn new(title: &str) -> Diag {
        Diag { level: "error", title: title.to_string(), annots: vec![], helps: vec![] }
    }
    pub fn primary(mut self, start: usize, end: usize, label: &str) -> Diag {
        self.annots.push(Annot { start, end, label: label.to_string(), primary: true });
        self
    }
    pub fn secondary(mut self, start: usize, end: usize, label: &str) -> Diag {
        self.annots.push(Annot { start, end, label: label.to_string(), primary: false });
        self
    }
    pub fn help(mut self, h: &str) -> Diag {
        self.helps.push(h.to_string());
        self
    }

    pub fn render(&self, source: &str) -> String {
        let mut out = String::new();
        out.push_str(&format!("{}: {}\n", self.level, self.title));
        let lines: Vec<&str> = source.split('\n').collect();
        let nlines = lines.len();
        let width = nlines.to_string().len();
        let pad = " ".repeat(width);
        out.push_str(&format!("{} |\n", pad));
        let mut line_start = 0usize;
        for (i, line) in lines.iter().enumerate() {
            let line_end = line_start + line.len();
            out.push_str(&format!("{:>w$} | {}\n", i + 1, line, w = width));
            // annotations on this line
            let mut anns: Vec<&Annot> = self
                .annots
                .iter()
                .filter(|a| {
                    let s = a.start;
                    (s >= line_start && s <= line_end && (i + 1 == nlines || s < line_end + 1))
                        && !(s == line_end + 1 && i + 1 < nlines)
                })
                .collect();
            // ensure an annotation belongs to exactly one line: start in [line_start, line_end]
            anns.retain(|a| a.start >= line_start && a.start <= line_end);
            if !anns.is_empty() {
                anns.sort_by_key(|a| a.start);
                let mut marks: Vec<char> = Vec::new();
                let mut label = String::new();
                for a in anns.iter() {
                    let s = a.start - line_start;
                    let e = if a.end > line_end { line_end - line_start } else { a.end - line_start };
                    let ch = if a.primary { '^' } else { '-' };
                    if e > s {
                        while marks.len() < e {
                            marks.push(' ');
                        }
                        for j in s..e {
                            marks[j] = ch;
                        }
                    } else if !a.primary {
                        // zero width secondary annotation is drawn one column to the right
                        let pos = s + 1;
                        while marks.len() < pos + 1 {
                            marks.push(' ');
                        }
                        marks[pos] = ch;
                    } else {
                        while marks.len() < s {
                            marks.push(' ');
                        }
                    }
                    if !a.label.is_empty() {
                        label = a.label.clone();
                    }
                }
                let mut ml: String = marks.into_iter().collect();
                if !label.is_empty() {
                    let trimmed = ml.trim_end().to_string();
                    ml = format!("{} {}", trimmed, label);
                }
                out.push_str(&format!("{} | {}\n", pad, ml));
            }
            line_start = line_end + 1;
        }
        out.push_str(&format!("{} |\n", pad));
        for h in &self.helps {
            out.push_str(&format!("{} = help: {}\n", pad, h));
        }
        out
    }
}
