cat > /workspace/src/lang.rs <<'EOF'
// Query parser.
use crate::ast::*;
use crate::diag::Diag;
use crate::value::Value;

pub const OPERATOR_NAMES: &[&str] = &[
    "json",
    "logfmt",
    "split",
    "parse",
    "fields",
    "where",
    "limit",
    "timeslice",
    "count",
    "min",
    "max",
    "sum",
    "average",
    "avg",
    "sort",
    "total",
    "count_distinct",
];

#[derive(Clone, Debug)]
pub struct AliasDef {
    pub keyword: String,
    pub template: String,
}

pub enum OpResult {
    Ok(Vec<Op>, usize),
    Fail,
}

pub struct Parser<'a> {
    pub src: &'a str,
    b: &'a [u8],
    pub errors: Vec<Diag>,
    aliases: &'a [AliasDef],
    pub alias_ops: &'a dyn Fn(&str) -> Option<Vec<Op>>,
}

fn is_ident_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_'
}
fn is_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}
fn is_ws(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r'
}

pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![i; b.len() + 1];
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        prev = cur;
    }
    prev[b.len()]
}

pub fn did_you_mean(word: &str) -> Option<&'static str> {
    let mut best: Option<(&'static str, f64)> = None;
    for cand in OPERATOR_NAMES {
        let d = levenshtein(word, cand);
        let maxlen = word.chars().count().max(cand.len());
        let sim = if maxlen == 0 { 1.0 } else { 1.0 - d as f64 / maxlen as f64 };
        if sim > 0.6 {
            match best {
                Some((_, s)) if s >= sim => {}
                _ => best = Some((cand, sim)),
            }
        }
    }
    best.map(|(c, _)| c)
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str, aliases: &'a [AliasDef], alias_ops: &'a dyn Fn(&str) -> Option<Vec<Op>>) -> Parser<'a> {
        Parser { src, b: src.as_bytes(), errors: vec![], aliases, alias_ops }
    }

    fn len(&self) -> usize {
        self.b.len()
    }

    fn at(&self, p: usize) -> u8 {
        if p < self.b.len() {
            self.b[p]
        } else {
            0
        }
    }

    pub fn ws(&self, mut p: usize) -> usize {
        while p < self.b.len() && is_ws(self.b[p]) {
            p += 1;
        }
        p
    }

    fn starts(&self, p: usize, s: &str) -> bool {
        p <= self.b.len() && self.b[p..].starts_with(s.as_bytes())
    }

    /// keyword match with word boundary
    fn kw(&self, p: usize, s: &str) -> Option<usize> {
        if self.starts(p, s) && !is_ident_char(self.at(p + s.len())) {
            Some(p + s.len())
        } else {
            None
        }
    }

    fn garbage_end(&self, p: usize) -> usize {
        let mut i = p;
        while i < self.b.len() && self.b[i] != b')' && self.b[i] != b'|' {
            i += 1;
        }
        i
    }

    fn pipe_end(&self, p: usize) -> usize {
        let mut i = p;
        while i < self.b.len() && self.b[i] != b'|' {
            i += 1;
        }
        i
    }

    fn word_end(&self, p: usize) -> usize {
        let mut i = p;
        while i < self.b.len() && !is_ws(self.b[i]) {
            i += 1;
        }
        i
    }

    fn report(&mut self, d: Diag) {
        self.errors.push(d);
    }

    fn ident(&self, p: usize) -> Option<(String, usize)> {
        if !is_ident_start(self.at(p)) {
            return None;
        }
        let mut i = p + 1;
        while i < self.b.len() && is_ident_char(self.b[i]) {
            i += 1;
        }
        Some((self.src[p..i].to_string(), i))
    }

    /// Parses a quoted string at p. Returns None if no quote at p.
    /// Unterminated strings are reported and consume the rest of the input.
    fn quoted_raw(&self, p: usize) -> Option<(String, usize, bool)> {
        let q = self.at(p);
        if q != b'"' && q != b'\'' {
            return None;
        }
        let mut out: Vec<u8> = Vec::new();
        let mut i = p + 1;
        while i < self.b.len() {
            let c = self.b[i];
            if c == b'\\' && i + 1 < self.b.len() {
                let n = self.b[i + 1];
                match n {
                    b'n' => out.push(b'\n'),
                    b't' => out.push(b'\t'),
                    b'r' => out.push(b'\r'),
                    b'0' => out.push(0),
                    b'\\' => out.push(b'\\'),
                    b'"' => out.push(b'"'),
                    b'\'' => out.push(b'\''),
                    _ => {
                        out.push(b'\\');
                        out.push(n);
                    }
                }
                i += 2;
                continue;
            }
            if c == q {
                return Some((String::from_utf8_lossy(&out).to_string(), i + 1, true));
            }
            out.push(c);
            i += 1;
        }
        Some((String::from_utf8_lossy(&out).to_string(), self.b.len(), false))
    }

    fn unterminated_string_diag(&self, p: usize) -> Diag {
        if self.at(p) == b'"' {
            Diag::new("unterminated double quoted string")
                .primary(p, self.len(), "")
                .help("Insert a double quote (\") to terminate this string")
        } else {
            Diag::new("unterminated single quoted string")
                .primary(p, self.len(), "")
                .help("Insert a single quote (') to terminate this string")
        }
    }

    fn quoted(&mut self, p: usize) -> Option<(String, usize)> {
        let (s, e, ok) = self.quoted_raw(p)?;
        if !ok {
            let d = self.unterminated_string_diag(p);
            self.report(d);
        }
        Some((s, e))
    }

    /// expects a quoted string; reports "expecting a quoted string" otherwise
    fn expect_quoted(&mut self, p: usize) -> (Option<String>, usize) {
        match self.quoted(p) {
            Some((s, e)) => (Some(s), e),
            None => {
                let mut e = self.word_end(p);
                if e == p {
                    e = p;
                }
                self.report(
                    Diag::new("expecting a quoted string")
                        .primary(p, e, "")
                        .help("Enclose the text in a single or double-quoted string"),
                );
                (None, e)
            }
        }
    }

    // ---------------------------------------------------------------- filter

    pub fn parse_query(&mut self) -> Option<(Search, Vec<Op>)> {
        let p = self.ws(0);
        let (search, mut pos) = if p >= self.len() || self.at(p) == b'|' {
            (Search::MatchAll, p)
        } else {
            let save = self.errors.len();
            match self.filter_top(p) {
                Some((s, e)) => {
                    let e2 = self.ws(e);
                    if e2 < self.len() && self.at(e2) != b'|' {
                        // dup errors x4 that were reported in the filter
                        return None;
                    }
                    let _ = save;
                    (s, e2)
                }
                None => return None,
            }
        };
        let mut ops = vec![];
        loop {
            pos = self.ws(pos);
            if pos >= self.len() {
                break;
            }
            if self.at(pos) != b'|' {
                break;
            }
            let p = self.ws(pos + 1);
            match self.operator(p) {
                OpResult::Ok(mut o, e) => {
                    ops.append(&mut o);
                    let e2 = self.ws(e);
                    if e2 < self.len() && self.at(e2) != b'|' {
                        break;
                    }
                    pos = e2;
                }
                OpResult::Fail => {
                    if self.errors.is_empty() {
                        self.generic_operator_error(p);
                    }
                    pos = self.pipe_end(p);
                }
            }
        }
        Some((search, ops))
    }

    fn generic_operator_error(&mut self, p: usize) {
        if let Some((id, e)) = self.ident(p) {
            if OPERATOR_NAMES.contains(&id.as_str()) || self.aliases.iter().any(|a| a.keyword == id) {
                return;
            }
            let mut d = Diag::new("Expected an operator")
                .primary(p, e, "")
                .help(&format!("{} is not a valid operator", id));
            if let Some(s) = did_you_mean(&id) {
                d = d.help(&format!("Did you mean \"{}\"?", s));
            }
            self.report(d);
            return;
        }
        let save = self.errors.len();
        let is_expr = self.expr(p).is_some();
        self.errors.truncate(save);
        let end = self.pipe_end(p);
        let (s, e) = if end == p { (p.saturating_sub(1), p) } else { (p, end) };
        if is_expr {
            self.report(Diag::new("unrecognized syntax").primary(s, e, ""));
        } else {
            self.report(Diag::new("expecting an expression").primary(s, e, ""));
        }
    }

    fn filter_top(&mut self, p: usize) -> Option<(Search, usize)> {
        let start_errs = self.errors.len();
        let mut terms = vec![];
        let (t, mut pos) = match self.filter_or(p) {
            Some(x) => x,
            None => {
                self.dup_errors(start_errs, 4);
                return None;
            }
        };
        terms.push(t);
        loop {
            let q = self.ws(pos);
            if q == pos || q >= self.len() || self.at(q) == b'|' {
                break;
            }
            let save = self.errors.len();
            match self.filter_or(q) {
                Some((t, e)) => {
                    terms.push(t);
                    pos = e;
                }
                None => {
                    self.dup_errors(save, 4);
                    break;
                }
            }
        }
        let s = if terms.len() == 1 { terms.pop().unwrap() } else { Search::And(terms) };
        Some((s, pos))
    }

    fn dup_errors(&mut self, from: usize, times: usize) {
        if self.errors.len() > from {
            let errs: Vec<Diag> = self.errors[from..].to_vec();
            for _ in 1..times {
                for e in errs.iter() {
                    self.errors.push(e.clone());
                }
            }
        }
    }

    fn filter_or(&mut self, p: usize) -> Option<(Search, usize)> {
        let (first, mut pos) = self.filter_and(p)?;
        let mut items = vec![first];
        loop {
            let q = self.ws(pos);
            if q > pos && self.starts(q, "OR") && q + 2 < self.len() && is_ws(self.at(q + 2)) {
                let r = self.ws(q + 2);
                match self.filter_and(r) {
                    Some((t, e)) => {
                        items.push(t);
                        pos = e;
                    }
                    None => return None,
                }
            } else {
                break;
            }
        }
        if items.len() == 1 {
            Some((items.pop().unwrap(), pos))
        } else {
            Some((Search::Or(items), pos))
        }
    }

    fn filter_and(&mut self, p: usize) -> Option<(Search, usize)> {
        let (first, mut pos) = self.filter_not(p)?;
        let mut items = vec![first];
        loop {
            let q = self.ws(pos);
            if q > pos && self.starts(q, "AND") && q + 3 < self.len() && is_ws(self.at(q + 3)) {
                let r = self.ws(q + 3);
                match self.filter_not(r) {
                    Some((t, e)) => {
                        items.push(t);
                        pos = e;
                    }
                    None => return None,
                }
            } else {
                break;
            }
        }
        if items.len() == 1 {
            Some((items.pop().unwrap(), pos))
        } else {
            Some((Search::And(items), pos))
        }
    }

    fn filter_not(&mut self, p: usize) -> Option<(Search, usize)> {
        if self.starts(p, "NOT") && p + 3 < self.len() && is_ws(self.at(p + 3)) {
            let r = self.ws(p + 3);
            if let Some((t, e)) = self.filter_not(r) {
                return Some((Search::Not(Box::new(t)), e));
            }
        }
        self.filter_atom(p)
    }

    fn filter_atom(&mut self, p: usize) -> Option<(Search, usize)> {
        let c = self.at(p);
        if c == b'(' {
            let q = self.ws(p + 1);
            let inner = self.filter_or(q);
            match inner {
                Some((t, e)) => {
                    let e2 = self.ws(e);
                    if self.at(e2) == b')' {
                        return Some((t, e2 + 1));
                    }
                    if e2 < self.len() {
                        let g = self.garbage_end(e);
                        if g < self.len() && self.at(g) == b')' {
                            self.report(Diag::new("unhandled input").primary(e, g, ""));
                            return Some((t, g + 1));
                        }
                    }
                    self.report(
                        Diag::new("unterminated parenthesized filter")
                            .primary(p, self.len(), "unterminated parenthesized filter")
                            .help("Insert a right parenthesis to terminate this filter"),
                    );
                    return None;
                }
                None => {
                    return None;
                }
            }
        }
        if c == b'"' || c == b'\'' {
            let (s, e, ok) = self.quoted_raw(p).unwrap();
            if !ok {
                let d = self.unterminated_string_diag(p);
                self.report(d);
                return None;
            }
            return Some((Search::Keyword { text: s, quoted: true }, e));
        }
        let mut i = p;
        while i < self.len() {
            let c = self.b[i];
            if c.is_ascii_alphanumeric() || b"-_./:@#$%^+*".contains(&c) {
                i += 1;
            } else {
                break;
            }
        }
        if i == p {
            return None;
        }
        let word = &self.src[p..i];
        if word.chars().all(|c| c == '*') {
            return Some((Search::MatchAll, i));
        }
        Some((Search::Keyword { text: word.to_string(), quoted: false }, i))
    }

    // ---------------------------------------------------------- expressions

    pub fn expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        self.or_expr(p)
    }

    fn or_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (mut l, mut pos) = self.and_expr(p)?;
        loop {
            let q = self.ws(pos);
            let (span_s, span_e, rhs_pos);
            if self.starts(q, "||") {
                let r = self.ws(q + 2);
                span_s = pos;
                span_e = r;
                rhs_pos = r;
            } else if q > pos && self.kw(q, "or").is_some() {
                span_s = q;
                span_e = q + 2;
                rhs_pos = q + 2;
            } else {
                break;
            }
            let r = self.ws(rhs_pos);
            match self.and_expr(r) {
                Some((rhs, e)) => {
                    l = Expr::Or(Box::new(l), Box::new(rhs));
                    pos = e;
                }
                None => {
                    self.report(
                        Diag::new("expecting an operand for 'or' operator")
                            .primary(span_s, span_e, "")
                            .secondary(rhs_pos, rhs_pos, "dangling 'or'")
                            .help("Add the operand or delete the 'or'"),
                    );
                    return Some((l, rhs_pos));
                }
            }
        }
        Some((l, pos))
    }

    fn and_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (mut l, mut pos) = self.cmp_expr(p)?;
        loop {
            let q = self.ws(pos);
            let (span_s, span_e, rhs_pos);
            if self.starts(q, "&&") {
                let r = self.ws(q + 2);
                span_s = pos;
                span_e = r;
                rhs_pos = r;
            } else if q > pos && self.kw(q, "and").is_some() {
                span_s = q;
                span_e = q + 3;
                rhs_pos = q + 3;
            } else {
                break;
            }
            let r = self.ws(rhs_pos);
            match self.cmp_expr(r) {
                Some((rhs, e)) => {
                    l = Expr::And(Box::new(l), Box::new(rhs));
                    pos = e;
                }
                None => {
                    self.report(
                        Diag::new("expecting an operand for 'and' operator")
                            .primary(span_s, span_e, "")
                            .secondary(rhs_pos, rhs_pos, "dangling 'and'")
                            .help("Add the operand or delete the 'and'"),
                    );
                    return Some((l, rhs_pos));
                }
            }
        }
        Some((l, pos))
    }

    fn cmp_op(&self, q: usize) -> Option<(CmpOp, usize)> {
        let ops: [(&str, CmpOp); 7] = [
            ("==", CmpOp::Eq),
            ("!=", CmpOp::Neq),
            ("<>", CmpOp::Neq),
            ("<=", CmpOp::Lte),
            (">=", CmpOp::Gte),
            ("<", CmpOp::Lt),
            (">", CmpOp::Gt),
        ];
        for (s, op) in ops.iter() {
            if self.starts(q, s) {
                return Some((*op, q + s.len()));
            }
        }
        None
    }

    fn cmp_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (l, pos) = self.add_expr(p)?;
        let q = self.ws(pos);
        if let Some((op, e)) = self.cmp_op(q) {
            let r = self.ws(e);
            match self.add_expr(r) {
                Some((rhs, e2)) => {
                    return Some((Expr::Cmp(op, Box::new(l), Box::new(rhs)), e2));
                }
                None => {
                    let g = self.garbage_end(r);
                    self.report(Diag::new("expecting the right-hand-side of the comparison").primary(r, g, ""));
                    return Some((Expr::Error, g));
                }
            }
        }
        Some((l, pos))
    }

    fn add_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (mut l, mut pos) = self.mul_expr(p)?;
        loop {
            let q = self.ws(pos);
            let op = match self.at(q) {
                b'+' => ArithOp::Add,
                b'-' => ArithOp::Sub,
                _ => break,
            };
            let r = self.ws(q + 1);
            match self.mul_expr(r) {
                Some((rhs, e)) => {
                    l = Expr::Arith(op, Box::new(l), Box::new(rhs));
                    pos = e;
                }
                None => {
                    let g = self.garbage_end(r);
                    self.report(
                        Diag::new("expecting an operand for binary operator")
                            .primary(r, g, "")
                            .secondary(g, g, "dangling binary operator")
                            .help("Add the operand or delete the operator"),
                    );
                    return Some((l, g));
                }
            }
        }
        Some((l, pos))
    }

    fn mul_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (mut l, mut pos) = self.unary_expr(p)?;
        loop {
            let q = self.ws(pos);
            let op = match self.at(q) {
                b'*' => ArithOp::Mul,
                b'/' => ArithOp::Div,
                _ => break,
            };
            let r = self.ws(q + 1);
            match self.unary_expr(r) {
                Some((rhs, e)) => {
                    l = Expr::Arith(op, Box::new(l), Box::new(rhs));
                    pos = e;
                }
                None => {
                    self.report(
                        Diag::new("expecting an operand for binary operator")
                            .primary(q, q + 1, "dangling binary operator")
                            .help("Add the operand or delete the operator"),
                    );
                    pos = r;
                }
            }
        }
        Some((l, pos))
    }

    fn unary_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        if self.at(p) == b'!' && self.at(p + 1) != b'=' {
            let u = p + 1;
            let r = self.ws(u);
            match self.unary_expr(r) {
                Some((e, end)) => return Some((Expr::Not(Box::new(e)), end)),
                None => {
                    let g = self.garbage_end(u);
                    self.report(
                        Diag::new("expecting expression for unary operator").primary(u, g, "").secondary(g, g, ""),
                    );
                    return Some((Expr::Error, g));
                }
            }
        }
        self.primary_expr(p)
    }

    /// Parses a parenthesized argument list starting at '(' (position p).
    /// Returns (args, end position, terminated)
    fn arg_list(&mut self, p: usize, single: bool) -> (Vec<Expr>, usize, bool, usize) {
        let mut args = vec![];
        let mut q = self.ws(p + 1);
        if let Some((e, end)) = self.expr(q) {
            args.push(e);
            q = end;
            if !single {
                loop {
                    let c = self.ws(q);
                    if self.at(c) == b',' {
                        let r = self.ws(c + 1);
                        let save = self.errors.len();
                        match self.expr(r) {
                            Some((e, end)) => {
                                args.push(e);
                                q = end;
                            }
                            None => {
                                self.errors.truncate(save);
                                break;
                            }
                        }
                    } else {
                        break;
                    }
                }
            }
        }
        let c = self.ws(q);
        if self.at(c) == b')' {
            return (args, c + 1, true, c);
        }
        let g = self.garbage_end(c);
        if g < self.len() && self.at(g) == b')' {
            self.report(Diag::new("unhandled input").primary(c, g, ""));
            return (args, g + 1, true, g);
        }
        (args, self.len(), false, self.len())
    }

    fn unterminated_call(&mut self, p: usize) {
        self.report(
            Diag::new("unterminated function call")
                .primary(p, self.len(), "unterminated function call")
                .help("Insert a right parenthesis to terminate this call"),
        );
    }

    fn primary_expr(&mut self, p: usize) -> Option<(Expr, usize)> {
        let c = self.at(p);
        if c == b'(' {
            let q = self.ws(p + 1);
            let inner = self.expr(q);
            let (e, end) = match inner {
                Some(x) => x,
                None => (Expr::Error, q),
            };
            let e2 = self.ws(end);
            if self.at(e2) == b')' {
                return Some((e, e2 + 1));
            }
            self.report(
                Diag::new("unterminated parenthesized expression")
                    .primary(p, self.len(), "unterminated parenthesized expression")
                    .help("Insert a right parenthesis to terminate this expression"),
            );
            return Some((e, self.len()));
        }
        if c == b'"' || c == b'\'' {
            let (s, e) = self.quoted(p).unwrap();
            return Some((Expr::Literal(Value::Str(s)), e));
        }
        if c.is_ascii_digit() {
            let mut i = p;
            while i < self.len() && self.b[i].is_ascii_digit() {
                i += 1;
            }
            let txt = &self.src[p..i];
            let v = match txt.parse::<i64>() {
                Ok(n) => Value::Int(n),
                Err(_) => Value::from_float(txt.parse::<f64>().unwrap_or(0.0)),
            };
            return Some((Expr::Literal(v), i));
        }
        if c == b'[' {
            return self.column(p);
        }
        if is_ident_start(c) {
            let (id, e) = self.ident(p).unwrap();
            if self.at(e) == b'(' {
                if id == "if" {
                    let (args, end, term, close) = self.arg_list(e, false);
                    if !term {
                        self.unterminated_call(e);
                    }
                    if args.len() != 3 {
                        self.report(
                            Diag::new("the 'if' operator expects exactly 3 arguments, the condition, value-if-true, and value-if-false")
                                .primary(e, if term { close + 1 } else { close }, &format!("supplied {} arguments", args.len())),
                        );
                        return Some((Expr::Error, end));
                    }
                    let mut it = args.into_iter();
                    let c = it.next().unwrap();
                    let t = it.next().unwrap();
                    let f = it.next().unwrap();
                    return Some((Expr::If(Box::new(c), Box::new(t), Box::new(f)), end));
                }
                let (args, end, term, _) = self.arg_list(e, false);
                if !term {
                    self.unterminated_call(e);
                }
                return Some((Expr::Call(id, args), end));
            }
            match id.as_str() {
                "true" => return Some((Expr::Literal(Value::Bool(true)), e)),
                "false" => return Some((Expr::Literal(Value::Bool(false)), e)),
                "null" => return Some((Expr::Literal(Value::None), e)),
                _ => {}
            }
            return self.column(p);
        }
        None
    }

    fn bracket_ident(&mut self, p: usize) -> Option<(String, usize)> {
        // p points at '['
        let q = p + 1;
        let (s, e, ok) = match self.quoted_raw(q) {
            Some(x) => x,
            None => return None,
        };
        if !ok {
            let d = self.unterminated_string_diag(q);
            self.report(d);
            self.report(
                Diag::new("unterminated identifier").primary(p, self.len(), "").help("Insert a closing square bracket"),
            );
            return Some((s, self.len()));
        }
        if self.at(e) == b']' {
            Some((s, e + 1))
        } else {
            self.report(
                Diag::new("unterminated identifier").primary(p, self.len(), "").help("Insert a closing square bracket"),
            );
            Some((s, self.len()))
        }
    }

    fn column(&mut self, p: usize) -> Option<(Expr, usize)> {
        let (head, mut pos) = if self.at(p) == b'[' {
            self.bracket_ident(p)?
        } else {
            self.ident(p)?
        };
        let mut rest = vec![];
        loop {
            if self.at(pos) == b'.' {
                if self.at(pos + 1) == b'[' {
                    if let Some((s, e)) = self.bracket_ident(pos + 1) {
                        rest.push(PathSeg::Field(s));
                        pos = e;
                        continue;
                    }
                    break;
                }
                if let Some((s, e)) = self.ident(pos + 1) {
                    rest.push(PathSeg::Field(s));
                    pos = e;
                    continue;
                }
                break;
            } else if self.at(pos) == b'[' {
                let mut i = pos + 1;
                let neg = self.at(i) == b'-';
                if neg {
                    i += 1;
                }
                let ds = i;
                while i < self.len() && self.b[i].is_ascii_digit() {
                    i += 1;
                }
                if i > ds && self.at(i) == b']' {
                    let n: i64 = self.src[ds..i].parse().unwrap_or(0);
                    rest.push(PathSeg::Index(if neg { -n } else { n }));
                    pos = i + 1;
                    continue;
                }
                break;
            } else {
                break;
            }
        }
        Some((Expr::Column { head, rest }, pos))
    }

    /// Parses a field name (identifier or ["quoted"]).
    fn field_name(&mut self, p: usize) -> Option<(String, usize)> {
        if self.at(p) == b'[' {
            return self.bracket_ident(p);
        }
        self.ident(p)
    }

    fn expect_field_name(&mut self, p: usize) -> (Option<String>, usize) {
        match self.field_name(p) {
            Some((s, e)) => (Some(s), e),
            None => {
                let g = self.garbage_end(p);
                self.report(Diag::new("expecting a name for the field").primary(p, g, "").help("Give the value a name"));
                (None, g)
            }
        }
    }

    fn expect_expr(&mut self, p: usize) -> (Option<Expr>, usize) {
        match self.expr(p) {
            Some((e, end)) => (Some(e), end),
            None => {
                let end = self.pipe_end(p);
                let (s, e) = if end == p { (p.saturating_sub(1), p) } else { (p, end) };
                self.report(Diag::new("expecting an expression").primary(s, e, ""));
                (None, end)
            }
        }
    }

    fn unrecognized_option(&mut self, q: usize, msg: &str) -> usize {
        let g = self.garbage_end(q);
        self.report(Diag::new(msg).primary(q, g, ""));
        g
    }

    /// checks for leftover text after an operator; reports `msg` if found
    fn check_end(&mut self, pos: usize, msg: &str) -> usize {
        let q = self.ws(pos);
        if q >= self.len() || self.at(q) == b'|' {
            return pos;
        }
        self.unrecognized_option(q, msg)
    }

    fn at_op_end(&self, pos: usize) -> bool {
        let q = self.ws(pos);
        q >= self.len() || self.at(q) == b'|'
    }

    // ------------------------------------------------------------ operators

    fn operator(&mut self, p: usize) -> OpResult {
        // aliases
        if let Some((id, e)) = self.ident(p) {
            if self.aliases.iter().any(|a| a.keyword == id) {
                if let Some(ops) = (self.alias_ops)(&id) {
                    return OpResult::Ok(ops, e);
                }
            }
        }
        if self.starts(p, "json") {
            if let Some(r) = self.op_json_like(p, "json", true) {
                return r;
            }
        }
        if self.starts(p, "logfmt") {
            if let Some(r) = self.op_json_like(p, "logfmt", false) {
                return r;
            }
        }
        if self.starts(p, "split") {
            if let Some(r) = self.op_split(p) {
                return r;
            }
        }
        if self.starts(p, "parse") {
            if let Some(r) = self.op_parse(p) {
                return r;
            }
        }
        if self.starts(p, "where") {
            if let Some(r) = self.op_where(p) {
                return r;
            }
        }
        if self.starts(p, "limit") {
            if let Some(r) = self.op_limit(p) {
                return r;
            }
        }
        if self.starts(p, "timeslice") {
            if let Some(r) = self.op_timeslice(p) {
                return r;
            }
        }
        if self.starts(p, "total") {
            if let Some(r) = self.op_total(p) {
                return r;
            }
        }
        if self.starts(p, "sort") {
            if let Some(r) = self.op_sort(p) {
                return r;
            }
        }
        // aggregates
        if let Some(r) = self.op_aggregates(p) {
            return r;
        }
        // field expression
        let save = self.errors.len();
        if let Some(r) = self.op_field_expr(p) {
            return r;
        }
        let had_err = self.errors.len() > save;
        if self.starts(p, "fields") {
            if let Some(r) = self.op_fields(p) {
                if had_err {
                    return OpResult::Fail;
                }
                return r;
            }
        }
        OpResult::Fail
    }

    fn op_json_like(&mut self, p: usize, name: &str, json: bool) -> Option<OpResult> {
        let e = p + name.len();
        let c = self.at(e);
        if c != 0 && !is_ws(c) && c != b'|' {
            return None;
        }
        let q = self.ws(e);
        let opt_msg = "unrecognized option, only the 'from' option is available";
        let mut from = None;
        let mut pos = e;
        if q > e {
            if let Some(fe) = self.kw(q, "from") {
                let r = self.ws(fe);
                match self.expr(r) {
                    Some((ex, end)) if r > fe => {
                        from = Some(ex);
                        pos = end;
                    }
                    _ => {
                        let msg = if json {
                            "expecting an expression that supplies a JSON-encoded string"
                        } else {
                            "expecting an expression that supplies a logfmt-serialized string"
                        };
                        self.report(Diag::new(msg).primary(q, fe, "should be followed by an expression"));
                        pos = self.ws(fe);
                    }
                }
            }
        }
        let pos = self.check_end(pos, opt_msg);
        let op = if json { Op::Json { from } } else { Op::Logfmt { from } };
        Some(OpResult::Ok(vec![op], pos))
    }

    fn op_split(&mut self, p: usize) -> Option<OpResult> {
        let mut pos = p + 5;
        let mut from = None;
        let opt_msg = "unrecognized option, only the 'on' and 'as' options are available";
        if self.at(pos) == b'(' {
            let (args, end, term, close) = self.arg_list(pos, true);
            if args.is_empty() {
                self.report(
                    Diag::new("this operator takes 1 argument, but 0 were supplied")
                        .secondary(close, close, "supplied 0 arguments")
                        .help("the argument should supply the string to split"),
                );
            }
            if !term {
                self.unterminated_call(pos);
            }
            from = args.into_iter().next();
            pos = end;
        } else {
            let c = self.at(pos);
            if c != 0 && !is_ws(c) && c != b'|' {
                return None;
            }
        }
        let mut sep = ",".to_string();
        let mut out = None;
        let q = self.ws(pos);
        if q > pos {
            if let Some(oe) = self.kw(q, "on") {
                let r = self.ws(oe);
                if r > oe {
                    let (s, e) = self.expect_quoted(r);
                    if let Some(s) = s {
                        sep = s;
                    }
                    pos = e;
                }
            }
        }
        let q = self.ws(pos);
        if q > pos {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae {
                    let (n, e) = self.expect_field_name(r);
                    out = n;
                    pos = e;
                }
            }
        }
        let pos = self.check_end(pos, opt_msg);
        Some(OpResult::Ok(vec![Op::Split { from, sep, out }], pos))
    }

    fn op_parse(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 5;
        if !is_ws(self.at(e)) {
            return None;
        }
        let mut pos = self.ws(e);
        let mut is_regex = false;
        if let Some(re) = self.starts(pos, "regex").then(|| pos + 5) {
            if is_ws(self.at(re)) {
                is_regex = true;
                pos = self.ws(re);
            }
        }
        let pat_start = pos;
        let (pat, pe) = self.expect_quoted(pos);
        let pat_end = pe;
        pos = pe;
        let opt_msg = "unrecognized option, only the 'from' and 'nodrop' options are available";
        let mut from = None;
        let mut fields = vec![];
        let mut nodrop = false;
        let mut noconvert = false;
        let mut has_as = false;
        let mut as_span = (0, 0);
        // from
        let try_from = |this: &mut Parser, pos: usize| -> Option<(Expr, usize)> {
            let q = this.ws(pos);
            if q > pos {
                if let Some(fe) = this.kw(q, "from") {
                    let r = this.ws(fe);
                    if r > fe {
                        if let Some((ex, end)) = this.expr(r) {
                            return Some((ex, end));
                        }
                    }
                }
            }
            None
        };
        if let Some((ex, end)) = try_from(self, pos) {
            from = Some(ex);
            pos = end;
        }
        let q = self.ws(pos);
        if q > pos {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae {
                    if let Some((n, e)) = self.field_name(r) {
                        has_as = true;
                        fields.push(n);
                        let mut cur = e;
                        loop {
                            if self.at(cur) == b',' {
                                let r2 = self.ws(cur + 1);
                                if let Some((n, e)) = self.field_name(r2) {
                                    fields.push(n);
                                    cur = e;
                                    continue;
                                }
                            }
                            break;
                        }
                        as_span = (q, cur);
                        pos = cur;
                    }
                }
            }
        }
        if from.is_none() {
            if let Some((ex, end)) = try_from(self, pos) {
                from = Some(ex);
                pos = end;
            }
        }
        let q = self.ws(pos);
        if q > pos && self.starts(q, "nodrop") {
            nodrop = true;
            pos = q + 6;
        }
        let q = self.ws(pos);
        if q > pos && self.starts(q, "noconvert") {
            noconvert = true;
            pos = q + 9;
        }
        let pos = self.check_end(pos, opt_msg);
        if is_regex {
            if has_as {
                self.report(
                    Diag::new("the parse regex operator does not support an 'as' clause")
                        .primary(as_span.0, as_span.1, "remove this")
                        .help("remove the 'as' clause, the named capture groups in the regular expression determine the output column"),
                );
            }
            let pat = pat.unwrap_or_default();
            match regex::Regex::new(&pat) {
                Ok(re) => {
                    let unnamed = re.capture_names().skip(1).filter(|n| n.is_none()).count();
                    if unnamed > 0 {
                        self.report(
                            Diag::new("regular expression for the parse operator cannot have unnamed captures")
                                .primary(pat_start, pat_end, &format!("contains {} unnamed capture(s)", unnamed))
                                .help("name the capture groups by adding -- ?P<capname> -- right after the left parenthesis"),
                        );
                    }
                    return Some(OpResult::Ok(vec![Op::ParseRegex { regex: re, from, nodrop, noconvert }], pos));
                }
                Err(err) => {
                    self.report(Diag::new("invalid regular expression").primary(pat_start, pat_end, &err.to_string()));
                    return Some(OpResult::Ok(vec![], pos));
                }
            }
        }
        Some(OpResult::Ok(
            vec![Op::Parse { pattern: pat.unwrap_or_default(), fields, from, nodrop, noconvert, pat_span: (pat_start, pat_end) }],
            pos,
        ))
    }

    fn op_where(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 5;
        let c = self.at(e);
        if c == 0 {
            // where without condition: semantic error later
            return Some(OpResult::Ok(vec![Op::Where(Expr::Literal(Value::None))], e)).map(|r| {
                self.where_missing = Some((p, e));
                r
            });
        }
        if !is_ws(c) {
            return None;
        }
        let r = self.ws(e);
        let (ex, end) = self.expect_expr(r);
        let ex = match ex {
            Some(x) => x,
            None => return Some(OpResult::Fail),
        };
        let pos = self.check_end(end, "unrecognized option, only the condition can be specified");
        Some(OpResult::Ok(vec![Op::Where(ex)], pos))
    }
