    fn op_where(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 5;
        let c = self.at(e);
        if c == 0 || c == b'|' {
            self.sem_errors.push((
                Diag::new("Expected an expression")
                    .primary(p, e, "No condition provided for this 'where'")
                    .help("Insert an expression whose result determines whether a record should be passed downstream")
                    .help("example: where duration > 100"),
                "Expected an expression".to_string(),
            ));
            return Some(OpResult::Ok(vec![Op::Where(Expr::Literal(Value::Bool(true)))], e));
        }
        if !is_ws(c) {
            return None;
        }
        let r = self.ws(e);
        let (ex, end) = self.expect_expr(r);
        let ex = match ex {
            Some(x) => x,
            None => return Some(OpResult::Fail),
        };
        let pos = self.check_end(end, "unrecognized option, only the condition can be specified");
        Some(OpResult::Ok(vec![Op::Where(ex)], pos))
    }

    /// parse a float the way nom's `double` does; returns (value, end)
    fn number(&self, p: usize) -> Option<(f64, usize)> {
        let mut i = p;
        if self.at(i) == b'+' || self.at(i) == b'-' {
            i += 1;
        }
        // inf / nan
        let lower: String = self.src[i..].chars().take(8).collect::<String>().to_ascii_lowercase();
        for w in ["infinity", "inf", "nan"] {
            if lower.starts_with(w) {
                let end = i + w.len();
                let txt = &self.src[p..end];
                return txt.parse::<f64>().ok().map(|v| (v, end));
            }
        }
        let ds = i;
        while self.at(i).is_ascii_digit() {
            i += 1;
        }
        let mut digits = i > ds;
        if self.at(i) == b'.' {
            let j = i + 1;
            let mut k = j;
            while self.at(k).is_ascii_digit() {
                k += 1;
            }
            if k > j || digits {
                digits = digits || k > j;
                i = k;
            }
        }
        if !digits {
            return None;
        }
        if self.at(i) == b'e' || self.at(i) == b'E' {
            let mut k = i + 1;
            if self.at(k) == b'+' || self.at(k) == b'-' {
                k += 1;
            }
            let es = k;
            while self.at(k).is_ascii_digit() {
                k += 1;
            }
            if k > es {
                i = k;
            }
        }
        let txt = &self.src[p..i];
        txt.parse::<f64>().ok().map(|v| (v, i))
    }

    fn op_limit(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 5;
        let c = self.at(e);
        let opt_msg = "unrecognized option, only the numeric limit can be specified";
        if c != 0 && !is_ws(c) && c != b'|' {
            return None;
        }
        let q = self.ws(e);
        if q == e || q >= self.len() || self.at(q) == b'|' {
            return Some(OpResult::Ok(vec![Op::Limit(10)], e));
        }
        match self.number(q) {
            Some((v, end)) => {
                let pos = self.check_end(end, opt_msg);
                if v == 0.0 {
                    self.sem_errors.push((
                        Diag::new(&format!("Limit must be a non-zero integer, found {}", v))
                            .primary(q, end, "Zero is not allowed")
                            .help("Use a positive integer to select the first N rows")
                            .help("Use a negative integer to select the last N rows"),
                        format!("Limit must be a non-zero integer, found {}", v),
                    ));
                } else if v.fract() != 0.0 {
                    self.sem_errors.push((
                        Diag::new(&format!("Limit must be a non-zero integer, found {}", v))
                            .primary(q, end, "Fractional limits are not allowed")
                            .help("Use a positive integer to select the first N rows")
                            .help("Use a negative integer to select the last N rows"),
                        format!("Limit must be a non-zero integer, found {}", v),
                    ));
                }
                Some(OpResult::Ok(vec![Op::Limit(v as i64)], pos))
            }
            None => {
                let pos = self.unrecognized_option(q, opt_msg);
                Some(OpResult::Ok(vec![Op::Limit(10)], pos))
            }
        }
    }

    fn parse_duration(&self, p: usize) -> Option<(chrono::TimeDelta, usize)> {
        let mut i = p;
        let mut total: i128 = 0;
        let mut any = false;
        loop {
            let ds = i;
            while self.at(i).is_ascii_digit() {
                i += 1;
            }
            if i == ds {
                break;
            }
            let n: i128 = self.src[ds..i].parse().ok()?;
            let units: [(&str, i128); 8] = [
                ("ns", 1),
                ("us", 1_000),
                ("ms", 1_000_000),
                ("s", 1_000_000_000),
                ("m", 60_000_000_000),
                ("h", 3_600_000_000_000),
                ("d", 86_400_000_000_000),
                ("w", 604_800_000_000_000),
            ];
            let mut matched = None;
            for (u, mult) in units.iter() {
                if self.starts(i, u) {
                    matched = Some((u.len(), *mult));
                    break;
                }
            }
            match matched {
                Some((l, mult)) => {
                    total += n * mult;
                    i += l;
                    any = true;
                }
                None => {
                    i = ds;
                    break;
                }
            }
        }
        if !any {
            return None;
        }
        if is_ident_char(self.at(i)) {
            return None;
        }
        let secs = (total / 1_000_000_000) as i64;
        let nanos = (total % 1_000_000_000) as u32;
        chrono::TimeDelta::new(secs, nanos).map(|d| (d, i))
    }

    fn op_timeslice(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 9;
        let opt_msg = "unrecognized option, only the 'as' option is available";
        if self.at(e) != b'(' {
            let c = self.at(e);
            if c != 0 && !is_ws(c) && c != b'|' && c != b'(' {
                // fallthrough to the error below
            }
            let g = self.garbage_end(e);
            self.report(
                Diag::new("expecting a parenthesized argument that supplies the date-time value for the log message")
                    .primary(e, g, ""),
            );
            return Some(OpResult::Fail);
        }
        let (args, end, term, close) = self.arg_list(e, true);
        if args.is_empty() {
            self.report(
                Diag::new("this operator takes 1 argument, but 0 were supplied").secondary(close, close, "supplied 0 arguments"),
            );
        }
        if !term {
            self.unterminated_call(e);
        }
        let expr = args.into_iter().next().unwrap_or(Expr::Error);
        let mut pos = end;
        let mut dur = None;
        let q = self.ws(pos);
        if q > pos {
            if let Some((d, de)) = self.parse_duration(q) {
                dur = Some(d);
                pos = de;
            }
        }
        let mut name = "_timeslice".to_string();
        let q = self.ws(pos);
        if q > pos {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae {
                    let (n, e2) = self.expect_field_name(r);
                    if let Some(n) = n {
                        name = n;
                    }
                    pos = e2;
                }
            }
        }
        let pos = self.check_end(pos, opt_msg);
        Some(OpResult::Ok(vec![Op::Timeslice { expr, dur, name }], pos))
    }

    fn op_total(&mut self, p: usize) -> Option<OpResult> {
        let e = p + 5;
        let opt_msg = "unrecognized option, only the 'as' option is available";
        if self.at(e) != b'(' {
            let g = self.garbage_end(e);
            self.report(Diag::new("expecting a parenthesized argument that supplies the value to sum").primary(e, g, ""));
            return Some(OpResult::Fail);
        }
        let (args, end, term, close) = self.arg_list(e, true);
        if args.is_empty() {
            self.report(
                Diag::new("this operator takes 1 argument, but 0 were supplied").secondary(close, close, "supplied 0 arguments"),
            );
        }
        if !term {
            self.unterminated_call(e);
        }
        let expr = args.into_iter().next().unwrap_or(Expr::Error);
        let mut pos = end;
        let mut name = "_total".to_string();
        let q = self.ws(pos);
        if q > pos {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae {
                    let (n, e2) = self.expect_field_name(r);
                    if let Some(n) = n {
                        name = n;
                    }
                    pos = e2;
                }
            }
        }
        let pos = self.check_end(pos, opt_msg);
        Some(OpResult::Ok(vec![Op::Total { expr, name }], pos))
    }

    /// comma separated expression list; returns (exprs with source text, end)
    fn expr_list(&mut self, p: usize) -> (Vec<(String, Expr)>, usize, bool) {
        let mut out = vec![];
        let (first, mut pos) = match self.expr(p) {
            Some(x) => x,
            None => return (out, p, false),
        };
        out.push((self.src[p..pos].trim().to_string(), first));
        loop {
            let c = self.ws(pos);
            if self.at(c) != b',' {
                break;
            }
            let r = self.ws(c + 1);
            match self.expr(r) {
                Some((e, end)) => {
                    out.push((self.src[r..end].trim().to_string(), e));
                    pos = end;
                }
                None => {
                    // trailing comma
                    let end = self.pipe_end(r);
                    let (s, e) = if end == r { (r.saturating_sub(1), r) } else { (r, end) };
                    let d = Diag::new("expecting an expression").primary(s, e, "");
                    self.report(d.clone());
                    self.report(d);
                    return (out, end, true);
                }
            }
        }
        (out, pos, false)
    }

    fn op_sort(&mut self, p: usize) -> Option<OpResult> {
        let mut pos = p + 4;
        let mut exprs = vec![];
        let mut desc = false;
        let q = self.ws(pos);
        if q > pos {
            if let Some(be) = self.kw(q, "by") {
                let r = self.ws(be);
                if r > be || r >= self.len() {
                    let save = self.errors.len();
                    let (list, end, failed) = self.expr_list(r);
                    if self.errors.len() > save && !failed {
                        self.dup_errors(save, 2);
                    }
                    if failed {
                        return Some(OpResult::Fail);
                    }
                    if list.is_empty() {
                        if r < self.len() && self.at(r) != b'|' {
                            // nothing parsable after 'by'
                            let end = self.pipe_end(r);
                            let d = Diag::new("expecting an expression").primary(r, end, "");
                            self.report(d.clone());
                            self.report(d);
                            return Some(OpResult::Fail);
                        }
                        pos = be;
                    } else {
                        exprs = list.into_iter().map(|(_, e)| e).collect();
                        pos = end;
                    }
                    let q2 = self.ws(pos);
                    if q2 > pos {
                        if let Some(de) = self.kw(q2, "descending").or_else(|| self.kw(q2, "desc")) {
                            desc = true;
                            pos = de;
                        } else if let Some(ae) = self.kw(q2, "ascending").or_else(|| self.kw(q2, "asc")) {
                            pos = ae;
                        }
                    }
                }
            }
        }
        Some(OpResult::Ok(vec![Op::Sort { exprs, desc }], pos))
    }

    fn op_fields(&mut self, p: usize) -> Option<OpResult> {
        let mut pos = p + 6;
        let mut mode = FieldMode::Only;
        let q = self.ws(pos);
        let mut fields = vec![];
        if q > pos || q == pos {
            let mut r = q;
            let mut saw_mode = false;
            for (m, md) in [("only", FieldMode::Only), ("except", FieldMode::Except), ("-", FieldMode::Except), ("+", FieldMode::Only)] {
                if q > pos && self.starts(q, m) {
                    mode = md;
                    r = self.ws(q + m.len());
                    saw_mode = true;
                    pos = q + m.len();
                    break;
                }
            }
            if q > pos || saw_mode {
                if let Some((n, e)) = self.field_column(r) {
                    fields.push(n);
                    let mut cur = e;
                    loop {
                        let c = self.ws(cur);
                        if self.at(c) == b',' {
                            let r2 = self.ws(c + 1);
                            if let Some((n, e)) = self.field_column(r2) {
                                fields.push(n);
                                cur = e;
                                continue;
                            }
                        }
                        break;
                    }
                    pos = cur;
                }
            }
        }
        if fields.is_empty() && mode == FieldMode::Only {
            mode = FieldMode::Except;
        }
        Some(OpResult::Ok(vec![Op::Fields { mode, fields }], pos))
    }

    /// a column reference used by `fields`; returns the top-level key
    fn field_column(&mut self, p: usize) -> Option<(String, usize)> {
        let save = self.errors.len();
        let r = self.column(p);
        match r {
            Some((Expr::Column { head, .. }, e)) => Some((head, e)),
            _ => {
                self.errors.truncate(save);
                None
            }
        }
    }

    fn op_field_expr(&mut self, p: usize) -> Option<OpResult> {
        let c = self.at(p);
        if !(is_ident_start(c) || c == b'(' || c == b'[' || c == b'"' || c == b'\'' || c == b'!' || c.is_ascii_digit()) {
            return None;
        }
        let (ex, end) = self.expr(p)?;
        let q = self.ws(end);
        if q > end {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae || r >= self.len() {
                    let (n, e) = self.expect_field_name(r);
                    let name = n.unwrap_or_default();
                    return Some(OpResult::Ok(vec![Op::FieldExpr { expr: ex, name }], e));
                }
            }
        }
        None
    }

    // ------------------------------------------------------------ aggregates

    fn agg_name_end(&self, p: usize) -> Option<(&'static str, usize, Option<f64>, String)> {
        // returns (kind, end_of_keyword, percentile, default name)
        if self.starts(p, "count_distinct") {
            return Some(("count_distinct", p + 14, None, "_countDistinct".into()));
        }
        if self.starts(p, "count") {
            return Some(("count", p + 5, None, "_count".into()));
        }
        if self.starts(p, "sum") {
            return Some(("sum", p + 3, None, "_sum".into()));
        }
        if self.starts(p, "min") {
            return Some(("min", p + 3, None, "_min".into()));
        }
        if self.starts(p, "max") {
            return Some(("max", p + 3, None, "_max".into()));
        }
        if self.starts(p, "average") {
            return Some(("avg", p + 7, None, "_average".into()));
        }
        if self.starts(p, "avg") {
            return Some(("avg", p + 3, None, "_average".into()));
        }
        for pre in ["percentile", "pct", "p"] {
            if self.starts(p, pre) {
                let ds = p + pre.len();
                let mut i = ds;
                while self.at(i).is_ascii_digit() {
                    i += 1;
                }
                if i > ds {
                    let txt = &self.src[ds..i];
                    let v: f64 = txt.parse().unwrap_or(0.0);
                    return Some(("pct", i, Some(v), format!("p{}", v)));
                }
            }
        }
        None
    }

    /// parse one aggregate function. Returns None if no aggregate keyword at p.
    fn aggregate(&mut self, p: usize) -> Option<(Option<Aggregate>, usize)> {
        let (kind, e, pct, default_name) = self.agg_name_end(p)?;
        let mut pos = e;
        let func;
        match kind {
            "count" => {
                if self.at(e) == b'(' {
                    let (args, end, term, close) = self.arg_list(e, true);
                    if args.is_empty() {
                        self.report(
                            Diag::new("this operator takes 1 argument, but 0 were supplied")
                                .secondary(close, close, "supplied 0 arguments"),
                        );
                    }
                    if !term {
                        self.unterminated_call(e);
                    }
                    func = AggFn::Count(args.into_iter().next());
                    pos = end;
                } else {
                    if is_ident_char(self.at(e)) {
                        return None;
                    }
                    func = AggFn::Count(None);
                }
            }
            "count_distinct" => {
                if self.at(e) == b'(' {
                    let (args, end, term, _close) = self.arg_list(e, false);
                    if !term {
                        self.unterminated_call(e);
                        return Some((None, end));
                    }
                    if args.len() != 1 {
                        let label = if args.is_empty() { "No expression given" } else { "Only a single expression can be given" };
                        self.report(
                            Diag::new("Expecting a single expression to count")
                                .primary(e, end, label)
                                .help("example: count_distinct(field_to_count)"),
                        );
                        return Some((None, end));
                    }
                    func = AggFn::CountDistinct(args.into_iter().next().unwrap());
                    pos = end;
                } else {
                    if is_ident_char(self.at(e)) {
                        return None;
                    }
                    if self.at_op_end(e) {
                        self.report(
                            Diag::new("Expecting an expression to count")
                                .primary(p, e, "No field argument given")
                                .help("example: count_distinct(field_to_count)"),
                        );
                        return Some((None, e));
                    }
                    return None;
                }
            }
            _ => {
                let what = match kind {
                    "sum" => "expecting a parenthesized argument that supplies the numeric value to find the sum of",
                    "min" => "expecting a parenthesized argument that supplies the numeric value to find the minimum of",
                    "max" => "expecting a parenthesized argument that supplies the numeric value to find the maximum of",
                    "avg" => "expecting a parenthesized argument that supplies the numeric value to find the average of",
                    _ => "expecting a parenthesized argument that supplies the value to compute the percentile of",
                };
                if self.at(e) != b'(' {
                    let g = self.garbage_end(e);
                    self.report(Diag::new(what).primary(e, g, ""));
                    return Some((None, g));
                }
                let (args, end, term, close) = self.arg_list(e, true);
                if args.is_empty() {
                    self.report(
                        Diag::new("this operator takes 1 argument, but 0 were supplied")
                            .secondary(close, close, "supplied 0 arguments"),
                    );
                }
                if !term {
                    self.unterminated_call(e);
                }
                let arg = args.into_iter().next().unwrap_or(Expr::Error);
                pos = end;
                func = match kind {
                    "sum" => AggFn::Sum(arg),
                    "min" => AggFn::Min(arg),
                    "max" => AggFn::Max(arg),
                    "avg" => AggFn::Avg(arg),
                    _ => {
                        let v = pct.unwrap();
                        let ds = e - self.src[..e].chars().rev().take_while(|c| c.is_ascii_digit()).count();
                        if v <= 0.0 || v >= 100.0 {
                            self.report(
                                Diag::new(&format!("invalid percentile number: {}", v))
                                    .primary(ds, e, "expecting a number between (0, 100)"),
                            );
                        }
                        AggFn::Pct(v / 100.0, arg)
                    }
                };
            }
        }
        // as name
        let mut name = default_name;
        let q = self.ws(pos);
        if q > pos {
            if let Some(ae) = self.kw(q, "as") {
                let r = self.ws(ae);
                if r > ae || r >= self.len() {
                    let (n, e2) = self.expect_field_name(r);
                    if let Some(n) = n {
                        name = n;
                    }
                    pos = e2;
                    if self.at(r) == 0 {
                        return Some((None, pos));
                    }
                }
            }
        }
        Some((Some(Aggregate { name, func }), pos))
    }

    fn op_aggregates(&mut self, p: usize) -> Option<OpResult> {
        let save = self.errors.len();
        let (first, mut pos) = self.aggregate(p)?;
        let mut aggs = vec![];
        let mut ok = true;
        match first {
            Some(a) => aggs.push(a),
            None => ok = false,
        }
        loop {
            let c = self.ws(pos);
            if self.at(c) != b',' {
                break;
            }
            let r = self.ws(c + 1);
            match self.aggregate(r) {
                Some((a, e)) => {
                    match a {
                        Some(a) => aggs.push(a),
                        None => ok = false,
                    }
                    pos = e;
                }
                None => {
                    if let Some((id, e)) = self.ident(r) {
                        self.report(
                            Diag::new("Not an aggregate operator")
                                .primary(r, e, "")
                                .help(&format!("{} is not a valid aggregate operator", id)),
                        );
                    }
                    return Some(OpResult::Fail);
                }
            }
        }
        let mut by = vec![];
        let q = self.ws(pos);
        if q > pos {
            if let Some(be) = self.kw(q, "by") {
                let r = self.ws(be);
                if r > be {
                    let esave = self.errors.len();
                    let (list, end, failed) = self.expr_list(r);
                    if failed {
                        return Some(OpResult::Fail);
                    }
                    if self.errors.len() > esave {
                        self.dup_errors(esave, 2);
                    }
                    if list.is_empty() {
                        let end = self.pipe_end(r);
                        let (s, e) = if end == r { (r.saturating_sub(1), r) } else { (r, end) };
                        let d = Diag::new("expecting an expression").primary(s, e, "");
                        self.report(d.clone());
                        self.report(d);
                        return Some(OpResult::Fail);
                    }
                    by = list;
                    pos = end;
                }
            }
        }
        if !ok && self.errors.len() > save {
            return Some(OpResult::Fail);
        }
        if !self.at_op_end(pos) {
            if self.errors.len() > save {
                return Some(OpResult::Fail);
            }
            return None;
        }
        if !ok {
            return None;
        }
        Some(OpResult::Ok(vec![Op::Agg { aggs, by }], pos))
    }
}
