    // date/duration arithmetic
    match (op, l, r) {
        (ArithOp::Sub, Value::DateTime(a), Value::DateTime(b)) => return Ok(Value::Duration(*a - *b)),
        (ArithOp::Add, Value::DateTime(a), Value::Duration(d)) => return Ok(Value::DateTime(*a + *d)),
        (ArithOp::Add, Value::Duration(d), Value::DateTime(a)) => return Ok(Value::DateTime(*a + *d)),
        (ArithOp::Sub, Value::DateTime(a), Value::Duration(d)) => return Ok(Value::DateTime(*a - *d)),
        (ArithOp::Add, Value::Duration(a), Value::Duration(b)) => return Ok(Value::Duration(*a + *b)),
        (ArithOp::Sub, Value::Duration(a), Value::Duration(b)) => return Ok(Value::Duration(*a - *b)),
        (ArithOp::Mul, Value::Duration(d), Value::Int(n)) | (ArithOp::Mul, Value::Int(n), Value::Duration(d)) => {
            return Ok(Value::Duration(*d * (*n as i32)))
        }
        (ArithOp::Div, Value::Duration(d), Value::Int(n)) => {
            if *n == 0 {
                return err("division by zero".to_string());
            }
            return Ok(Value::Duration(*d / (*n as i32)));
        }
        _ => {}
    }
    let fail = || err(format!("Expected numeric operands, found {} {} {}", l.to_func_string(), op_str(op), r.to_func_string()));
    if matches!(l, Value::Duration(_)) || matches!(r, Value::Duration(_)) {
        return fail();
    }
    let a = match arith_num(l) {
        Some(n) => n,
        None => return fail(),
    };
    let b = match arith_num(r) {
        Some(n) => n,
        None => return fail(),
    };
    match (a, b) {
        (Num::Int(x), Num::Int(y)) => match op {
            ArithOp::Add => Ok(Value::Int(x.wrapping_add(y))),
            ArithOp::Sub => Ok(Value::Int(x.wrapping_sub(y))),
            ArithOp::Mul => Ok(Value::Int(x.wrapping_mul(y))),
            ArithOp::Div => Ok(Value::from_float(x as f64 / y as f64)),
        },
        _ => {
            let x = a.as_f64();
            let y = b.as_f64();
            let res = match op {
                ArithOp::Add => x + y,
                ArithOp::Sub => x - y,
                ArithOp::Mul => x * y,
                ArithOp::Div => x / y,
            };
            Ok(Value::from_float(res))
        }
    }
}

pub fn compare(op: CmpOp, l: &Value, r: &Value) -> bool {
    use std::cmp::Ordering::*;
    match op {
        CmpOp::Eq => l == r,
        CmpOp::Neq => l != r,
        CmpOp::Lt => l.partial_compare(r) == Some(Less),
        CmpOp::Lte => matches!(l.partial_compare(r), Some(Less) | Some(Equal)),
        CmpOp::Gt => l.partial_compare(r) == Some(Greater),
        CmpOp::Gte => matches!(l.partial_compare(r), Some(Greater) | Some(Equal)),
    }
}

pub fn eval(e: &Expr, data: &Data) -> EResult {
    match e {
        Expr::Column { head, rest } => lookup(data, head, rest).map(|v| v.clone()),
        Expr::Literal(v) => Ok(v.clone()),
        Expr::Arith(op, l, r) => {
            let lv = eval(l, data)?;
            let rv = eval(r, data)?;
            arith(*op, &lv, &rv)
        }
        Expr::Cmp(op, l, r) => {
            let lv = eval(l, data)?;
            let rv = eval(r, data)?;
            Ok(Value::Bool(compare(*op, &lv, &rv)))
        }
        Expr::And(l, r) => {
            let lv = eval(l, data)?;
            if !expect_bool(&lv)? {
                return Ok(Value::Bool(false));
            }
            eval(r, data)
        }
        Expr::Or(l, r) => {
            let lv = eval(l, data)?;
            if expect_bool(&lv)? {
                return Ok(Value::Bool(true));
            }
            eval(r, data)
        }
        Expr::Not(x) => {
            let v = eval(x, data)?;
            Ok(Value::Bool(!expect_bool(&v)?))
        }
        Expr::If(c, t, f) => {
            let cv = eval(c, data)?;
            if expect_bool(&cv)? {
                eval(t, data)
            } else {
                eval(f, data)
            }
        }
        Expr::Call(name, args) => {
            let mut vals = Vec::with_capacity(args.len());
            for a in args {
                vals.push(eval(a, data)?);
            }
            call_function(name, &vals)
        }
        Expr::Error => Ok(Value::None),
    }
}

