pub fn function_exists(name: &str) -> bool {
    FUNCTIONS.iter().any(|(n, _)| *n == name)
}

fn expect_number(v: &Value) -> Result<f64, EvalError> {
    match v.as_number() {
        Some(n) => Ok(n.as_f64()),
        None => err(format!("Expected number, found {}", v)),
    }
}

fn num_filter(s: &str) -> Option<f64> {
    let filtered: String = s.chars().filter(|c| c.is_ascii_digit() || *c == '.').collect();
    filtered.parse::<f64>().ok()
}

fn func_num(v: &Value) -> EResult {
    match v {
        Value::Int(_) | Value::Float(_) => Ok(v.clone()),
        Value::Str(s) => match num_filter(s) {
            Some(f) => Ok(Value::from_float(f)),
            None => err(format!("Expected number, found {}", v)),
        },
        _ => err(format!("Expected number, found {}", v)),
    }
}

fn positive_number(v: &Value) -> Result<usize, EvalError> {
    match v {
        Value::None | Value::Bool(_) | Value::Array(_) | Value::Obj(_) => {
            err(format!("Expected positive number, found {}", v))
        }
        _ => {
            let n = expect_number(v)?;
            if n < 0.0 {
                return err(format!("Expected positive number, found {}", v));
            }
            Ok(n as usize)
        }
    }
}

fn func_failed(name: &str, msg: String) -> EvalError {
    EvalError(format!("The '{}' function failed with the error: {}", name, msg))
}

pub fn call_function(name: &str, args: &[Value]) -> EResult {
    let arity = FUNCTIONS.iter().find(|(n, _)| *n == name).map(|(_, a)| *a);
    let arity = match arity {
        Some(a) => a,
        None => return err(format!("Unknown function {}", name)),
    };
    if arity == usize::MAX - 1 {
        // substring: 2 or 3 args
        if args.len() < 2 || args.len() > 3 {
            return err(format!("The '{}' function expects 2 to 3 arguments, found {}", name, args.len()));
        }
    } else if arity != usize::MAX && args.len() != arity {
        return err(format!("The '{}' function expects {} arguments, found {}", name, arity, args.len()));
    }
    let math1 = |f: fn(f64) -> f64| -> EResult {
        let x = expect_number(&args[0])?;
        Ok(Value::from_float(f(x)))
    };
    match name {
        "abs" => {
            if let Value::Int(i) = &args[0] {
                return Ok(Value::Int(i.wrapping_abs()));
            }
            math1(f64::abs)
        }
        "acos" => math1(f64::acos),
        "asin" => math1(f64::asin),
        "atan" => math1(f64::atan),
        "cbrt" => math1(f64::cbrt),
        "ceil" => math1(f64::ceil),
        "cos" => math1(f64::cos),
        "cosh" => math1(f64::cosh),
        "exp" => math1(f64::exp),
        "expm1" => math1(f64::exp_m1),
        "floor" => math1(f64::floor),
        "log" => math1(f64::ln),
        "log10" => math1(f64::log10),
        "log1p" => math1(f64::ln_1p),
        "round" => math1(f64::round),
        "sin" => math1(f64::sin),
        "sinh" => math1(f64::sinh),
        "sqrt" => math1(f64::sqrt),
        "tan" => math1(f64::tan),
        "tanh" => math1(f64::tanh),
        "toDegrees" => math1(f64::to_degrees),
        "toRadians" => math1(f64::to_radians),
        "atan2" => {
            let y = expect_number(&args[0])?;
            let x = expect_number(&args[1])?;
            Ok(Value::from_float(y.atan2(x)))
        }
        "hypot" => {
            let x = expect_number(&args[0])?;
            let y = expect_number(&args[1])?;
            Ok(Value::from_float(x.hypot(y)))
        }
        "concat" => {
            let mut s = String::new();
            for a in args {
                s.push_str(&a.to_func_string());
            }
            Ok(Value::Str(s))
        }
        "contains" => {
            let h = args[0].to_func_string();
            let n = args[1].to_func_string();
            Ok(Value::Bool(h.contains(&n)))
        }
        "length" => match &args[0] {
            Value::Array(a) => Ok(Value::Int(a.len() as i64)),
            Value::Obj(o) => Ok(Value::Int(o.len() as i64)),
            v => Ok(Value::Int(v.to_func_string().chars().count() as i64)),
        },
        "now" => Ok(Value::DateTime(Utc::now())),
        "num" => func_num(&args[0]),
        "isNumeric" => match &args[0] {
            Value::Int(_) | Value::Float(_) => Ok(Value::Bool(true)),
            Value::Str(s) => Ok(Value::Bool(num_filter(s).is_some())),
            _ => Ok(Value::Bool(false)),
        },
        "parseDate" => {
            let s = args[0].to_func_string();
            match crate::dtparse::parse(&s) {
                Ok(d) => Ok(Value::DateTime(d)),
                Err(e) => Err(func_failed("parseDate", e)),
            }
        }
        "parseHex" => {
            let s = args[0].to_func_string();
            let t = s.trim();
            let (neg, t2) = if let Some(r) = t.strip_prefix('-') { (true, r) } else { (false, t) };
            let t3 = t2.strip_prefix("0x").unwrap_or(t2);
            match i64::from_str_radix(t3, 16) {
                Ok(v) if !t3.starts_with('+') && !t3.starts_with('-') => Ok(Value::Int(if neg { -v } else { v })),
                _ => Err(func_failed("parseHex", format!("invalid hex string -- {}", s))),
            }
        }
        "substring" => {
            let s = args[0].to_func_string();
            let chars: Vec<char> = s.chars().collect();
            let start = positive_number(&args[1])?;
            let end = if args.len() == 3 { Some(positive_number(&args[2])?) } else { None };
            if let Some(e) = end {
                if e < start {
                    return Err(func_failed(
                        "substring",
                        format!("end offset ({}) is less than the start offset ({})", e, start),
                    ));
                }
            }
            let st = start.min(chars.len());
            let en = end.unwrap_or(chars.len()).min(chars.len());
            Ok(Value::Str(chars[st..en.max(st)].iter().collect()))
        }
        "toLowerCase" => Ok(Value::from_string(&args[0].to_func_string().to_lowercase())),
        "toUpperCase" => Ok(Value::from_string(&args[0].to_func_string().to_uppercase())),
        "isNull" => Ok(Value::Bool(args[0].is_none())),
        "isEmpty" => Ok(Value::Bool(match &args[0] {
            Value::None => true,
            Value::Str(s) => s.is_empty(),
            _ => false,
        })),
        "isBlank" => Ok(Value::Bool(match &args[0] {
            Value::None => true,
            Value::Str(s) => s.trim().is_empty(),
            _ => false,
        })),
        _ => err(format!("Unknown function {}", name)),
    }
}

pub fn check_functions(e: &Expr) -> Result<(), String> {
    match e {
        Expr::Call(name, args) => {
            if !function_exists(name) {
                return Err(format!("Unknown function {}", name));
            }
            for a in args {
                check_functions(a)?;
            }
            Ok(())
        }
        Expr::Arith(_, l, r) | Expr::Cmp(_, l, r) | Expr::And(l, r) | Expr::Or(l, r) => {
            check_functions(l)?;
            check_functions(r)
        }
        Expr::Not(x) => check_functions(x),
        Expr::If(a, b, c) => {
            check_functions(a)?;
            check_functions(b)?;
            check_functions(c)
        }
        _ => Ok(()),
    }
}

