pub fn logfmt_parse(line: &str) -> Vec<(String, Option<String>)> {
    let mut out = vec![];
    let mut key = String::new();
    let mut val = String::new();
    let mut in_value = false;
    let mut in_quote = false;
    let mut escape = false;
    let emit = |out: &mut Vec<(String, Option<String>)>, key: &mut String, val: &mut String, in_value: bool| {
        if !key.is_empty() {
            out.push((key.clone(), if in_value { Some(val.clone()) } else { None }));
        }
        key.clear();
        val.clear();
    };
    for c in line.chars() {
        if in_quote {
            if escape {
                escape = false;
                let buf = if in_value { &mut val } else { &mut key };
                if c == '"' || c == '\\' {
                    buf.push(c);
                } else {
                    buf.push('\\');
                    buf.push(c);
                }
                continue;
            }
            if c == '\\' {
                escape = true;
                continue;
            }
            if c == '"' {
                in_quote = false;
                continue;
            }
            if in_value {
                val.push(c);
            } else {
                key.push(c);
            }
            continue;
        }
        match c {
            ' ' => {
                if in_value {
                    if val.is_empty() {
                        continue;
                    }
                    emit(&mut out, &mut key, &mut val, true);
                    in_value = false;
                } else {
                    emit(&mut out, &mut key, &mut val, false);
                }
            }
            '=' => {
                if in_value {
                    key = std::mem::take(&mut val);
                } else {
                    in_value = true;
                }
            }
            '"' => in_quote = true,
            _ => {
                if in_value {
                    val.push(c);
                } else {
                    key.push(c);
                }
            }
        }
    }
    emit(&mut out, &mut key, &mut val, in_value);
    out
}

pub fn split_quoted(input: &str, sep: &str) -> Vec<String> {
    let chars: Vec<char> = input.chars().collect();
    let sepc: Vec<char> = sep.chars().collect();
    let mut out = vec![];
    if sepc.is_empty() {
        out.push(input.to_string());
        return out;
    }
    let n = chars.len();
    let mut i = 0;
    let starts_sep = |i: usize| -> bool { i + sepc.len() <= n && chars[i..i + sepc.len()] == sepc[..] };
    while i < n {
        let c = chars[i];
        if c == '"' || c == '\'' {
            let q = c;
            let mut j = i + 1;
            let mut tok = String::new();
            let mut closed = false;
            while j < n {
                if chars[j] == '\\' && j + 1 < n {
                    tok.push(chars[j]);
                    tok.push(chars[j + 1]);
                    j += 2;
                    continue;
                }
                if chars[j] == q {
                    closed = true;
                    break;
                }
                tok.push(chars[j]);
                j += 1;
            }
            if closed {
                out.push(tok);
                i = j + 1;
                if starts_sep(i) {
                    i += sepc.len();
                }
                continue;
            }
        }
        // read until separator
        let mut tok = String::new();
        while i < n && !starts_sep(i) {
            tok.push(chars[i]);
            i += 1;
        }
        out.push(tok);
        if starts_sep(i) {
            i += sepc.len();
        }
    }
    out.into_iter().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
}

pub fn build_parse_regex(pattern: &str) -> (regex::Regex, usize) {
    let mut re = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut count = 0;
    for (i, c) in chars.iter().enumerate() {
        if *c == '*' {
            count += 1;
            if i + 1 == chars.len() {
                re.push_str("(.*)");
            } else {
                re.push_str("(.*?)");
            }
        } else if c.is_whitespace() {
            re.push_str(r"\s");
        } else {
            re.push_str(&regex::escape(&c.to_string()));
        }
    }
    (regex::RegexBuilder::new(&re).dot_matches_new_line(true).build().unwrap(), count)
}

