                Ok(other) => RowResult::Err(format!(
                    "Expected date, found '{}'.  Use parseDate() to convert a value to a date",
                    other
                )),
                Err(EvalError(m)) => RowResult::Err(m),
            },
            RowOp::Total { expr, name, total } => {
                if let Ok(v) = eval(expr, &rec.data) {
                    if let Some(n) = v.as_number() {
                        *total += n.as_f64();
                    }
                }
                rec.data.insert(name.clone(), Value::from_float(*total));
                RowResult::Keep(rec)
            }
            RowOp::Limit { n, seen } => {
                if *seen >= *n {
                    return RowResult::Drop;
                }
                *seen += 1;
                RowResult::Keep(rec)
            }
        }
    }

    pub fn limit_done(&self) -> bool {
        match self {
            RowOp::Limit { n, seen } => *seen >= *n,
            _ => false,
        }
    }
}

// ------------------------------------------------------------- aggregates

pub struct Frame {
    pub columns: Vec<String>,
    pub rows: Vec<Data>,
}

enum AggState {
    Count(i64),
    Sum(Option<crate::value::Num>),
    Min(Option<Value>),
    Max(Option<Value>),
    Avg(f64, i64),
    Pct(Ckms),
    Distinct(HashSet<Value>),
}

fn new_state(f: &AggFn) -> AggState {
    match f {
        AggFn::Count(_) => AggState::Count(0),
        AggFn::Sum(_) => AggState::Sum(None),
        AggFn::Min(_) => AggState::Min(None),
        AggFn::Max(_) => AggState::Max(None),
        AggFn::Avg(_) => AggState::Avg(0.0, 0),
        AggFn::Pct(_, _) => AggState::Pct(Ckms::new(0.001)),
        AggFn::CountDistinct(_) => AggState::Distinct(HashSet::new()),
    }
}

fn update_state(st: &mut AggState, f: &AggFn, data: &Data) {
    use crate::value::Num;
    match (st, f) {
        (AggState::Count(c), AggFn::Count(cond)) => match cond {
            None => *c += 1,
            Some(e) => {
                if let Ok(Value::Bool(true)) = eval(e, data) {
                    *c += 1
                }
            }
        },
        (AggState::Sum(s), AggFn::Sum(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    *s = Some(match (*s, n) {
                        (None, n) => n,
                        (Some(Num::Int(a)), Num::Int(b)) => Num::Int(a.wrapping_add(b)),
                        (Some(a), b) => Num::Float(a.as_f64() + b.as_f64()),
                    });
                }
            }
        }
        (AggState::Min(m), AggFn::Min(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    let nv = n.to_value();
                    let replace = match m {
                        None => true,
                        Some(cur) => nv.partial_compare(cur) == Some(std::cmp::Ordering::Less),
                    };
                    if replace {
                        *m = Some(nv);
                    }
                }
            }
        }
        (AggState::Max(m), AggFn::Max(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    let nv = n.to_value();
                    let replace = match m {
                        None => true,
                        Some(cur) => nv.partial_compare(cur) == Some(std::cmp::Ordering::Greater),
                    };
                    if replace {
                        *m = Some(nv);
                    }
                }
            }
        }
        (AggState::Avg(s, c), AggFn::Avg(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    *s += n.as_f64();
                    *c += 1;
                }
            }
        }
        (AggState::Pct(ck), AggFn::Pct(_, e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    ck.insert(n.as_f64());
                }
            }
        }
        (AggState::Distinct(set), AggFn::CountDistinct(e)) => {
            if let Ok(v) = eval(e, data) {
                set.insert(v);
            }
        }
        _ => {}
    }
}

fn finish_state(st: &AggState, f: &AggFn) -> Value {
    match (st, f) {
        (AggState::Count(c), _) => Value::Int(*c),
        (AggState::Sum(s), _) => match s {
            None => Value::Int(0),
            Some(n) => n.to_value(),
        },
        (AggState::Min(m), _) | (AggState::Max(m), _) => m.clone().unwrap_or(Value::None),
        (AggState::Avg(s, c), _) => Value::from_float(*s / *c as f64),
        (AggState::Pct(ck), AggFn::Pct(q, _)) => match ck.query(*q) {
            Some(v) => Value::from_float(v),
            None => Value::None,
        },
        (AggState::Distinct(set), _) => Value::Int(set.len() as i64),
        _ => Value::None,
    }
}

pub struct Grouper {
    aggs: Vec<Aggregate>,
    by: Vec<(String, Expr)>,
    groups: HashMap<Vec<Value>, Vec<AggState>>,
    order: Vec<Vec<Value>>,
}

impl Grouper {
    pub fn new(aggs: Vec<Aggregate>, by: Vec<(String, Expr)>) -> Grouper {
        Grouper { aggs, by, groups: HashMap::new(), order: vec![] }
    }

    pub fn add(&mut self, data: &Data) {
        let key: Vec<Value> = self.by.iter().map(|(_, e)| eval(e, data).unwrap_or(Value::None)).collect();
        if !self.groups.contains_key(&key) {
            let states = self.aggs.iter().map(|a| new_state(&a.func)).collect();
            self.groups.insert(key.clone(), states);
            self.order.push(key.clone());
        }
        let states = self.groups.get_mut(&key).unwrap();
        for (st, a) in states.iter_mut().zip(self.aggs.iter()) {
            update_state(st, &a.func, data);
        }
    }

    pub fn finish(&self) -> Frame {
        let mut columns: Vec<String> = self.by.iter().map(|(n, _)| n.clone()).collect();
        for a in &self.aggs {
            columns.push(a.name.clone());
        }
        let mut rows: Vec<Data> = vec![];
        let mut keys = self.order.clone();
        if self.by.is_empty() && keys.is_empty() {
            keys.push(vec![]);
        }
        for k in keys.iter() {
            let mut d = Data::new();
            for (i, (n, _)) in self.by.iter().enumerate() {
                d.insert(n.clone(), k[i].clone());
            }
            let fresh;
            let states = match self.groups.get(k) {
                Some(s) => s,
                None => {
                    fresh = self.aggs.iter().map(|a| new_state(&a.func)).collect::<Vec<_>>();
                    &fresh
                }
            };
            for (st, a) in states.iter().zip(self.aggs.iter()) {
                d.insert(a.name.clone(), finish_state(st, &a.func));
            }
            rows.push(d);
        }
        let agg_names: Vec<String> = self.aggs.iter().map(|a| a.name.clone()).collect();
        let key_names: Vec<String> = self.by.iter().map(|(n, _)| n.clone()).collect();
        rows.sort_by(|a, b| {
            for n in &agg_names {
                let va = a.get(n).unwrap_or(&Value::None);
                let vb = b.get(n).unwrap_or(&Value::None);
                let o = vb.total_cmp(va);
                if o != std::cmp::Ordering::Equal {
                    return o;
                }
            }
            for n in &key_names {
                let va = a.get(n).unwrap_or(&Value::None);
                let vb = b.get(n).unwrap_or(&Value::None);
                let o = va.total_cmp(vb);
                if o != std::cmp::Ordering::Equal {
                    return o;
                }
            }
            std::cmp::Ordering::Equal
        });
        Frame { columns, rows }
    }
}

pub fn sort_frame(frame: &mut Frame, exprs: &[Expr], desc: bool) {
    let cols = frame.columns.clone();
    let mut keyed: Vec<(Vec<Value>, Data)> = frame
        .rows
        .drain(..)
        .map(|d| {
            let k: Vec<Value> = exprs.iter().map(|e| eval(e, &d).unwrap_or(Value::None)).collect();
            (k, d)
        })
        .collect();
    keyed.sort_by(|(ka, a), (kb, b)| {
        for (x, y) in ka.iter().zip(kb.iter()) {
            let o = x.total_cmp(y);
            if o != std::cmp::Ordering::Equal {
                return if desc { o.reverse() } else { o };
            }
        }
        for c in &cols {
            let va = a.get(c).unwrap_or(&Value::None);
            let vb = b.get(c).unwrap_or(&Value::None);
            let o = va.total_cmp(vb);
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        std::cmp::Ordering::Equal
    });
    frame.rows = keyed.into_iter().map(|(_, d)| d).collect();
}
