use crate::ast::*;
use crate::ckms::Ckms;
use crate::eval::{eval, Data, EvalError};
use crate::value::Value;
use std::collections::{HashMap, HashSet};

#[derive(Clone)]
pub struct Record {
    pub data: Data,
    pub raw: Option<String>,
}

pub enum RowResult {
    Keep(Record),
    Drop,
    Err(String),
}

fn get_input(from: &Option<Expr>, rec: &Record) -> Result<Option<String>, String> {
    match from {
        None => Ok(rec.raw.clone()),
        Some(e) => match eval(e, &rec.data) {
            Ok(Value::Str(s)) => Ok(Some(s)),
            Ok(Value::None) => Err("Found None, expected String".to_string()),
            Ok(_) => Err("Expected string, found other".to_string()),
            Err(EvalError(m)) => Err(m),
        },
    }
}

pub fn logfmt_parse(line: &str) -> Vec<(String, Option<String>)> {
    let mut out = vec![];
    let mut key = String::new();
    let mut val = String::new();
    let mut in_value = false;
    let mut in_quote = false;
    let mut escape = false;
    let emit = |out: &mut Vec<(String, Option<String>)>, key: &mut String, val: &mut String, in_value: bool| {
        if !key.is_empty() {
            out.push((key.clone(), if in_value { Some(val.clone()) } else { None }));
        }
        key.clear();
        val.clear();
    };
    for c in line.chars() {
        if in_quote {
            if escape {
                escape = false;
                let buf = if in_value { &mut val } else { &mut key };
                if c == '"' || c == '\\' {
                    buf.push(c);
                } else {
                    buf.push('\\');
                    buf.push(c);
                }
                continue;
            }
            if c == '\\' {
                escape = true;
                continue;
            }
            if c == '"' {
                in_quote = false;
                continue;
            }
            if in_value {
                val.push(c);
            } else {
                key.push(c);
            }
            continue;
        }
        match c {
            ' ' => {
                if in_value {
                    if val.is_empty() {
                        continue;
                    }
                    emit(&mut out, &mut key, &mut val, true);
                    in_value = false;
                } else {
                    emit(&mut out, &mut key, &mut val, false);
                }
            }
            '=' => {
                if in_value {
                    key = std::mem::take(&mut val);
                } else {
                    in_value = true;
                }
            }
            '"' => in_quote = true,
            _ => {
                if in_value {
                    val.push(c);
                } else {
                    key.push(c);
                }
            }
        }
    }
    emit(&mut out, &mut key, &mut val, in_value);
    out
}

pub fn split_quoted(input: &str, sep: &str) -> Vec<String> {
    let chars: Vec<char> = input.chars().collect();
    let sepc: Vec<char> = sep.chars().collect();
    let mut out = vec![];
    if sepc.is_empty() {
        out.push(input.to_string());
        return out;
    }
    let n = chars.len();
    let mut i = 0;
    let starts_sep = |i: usize| -> bool { i + sepc.len() <= n && chars[i..i + sepc.len()] == sepc[..] };
    while i < n {
        let c = chars[i];
        if c == '"' || c == '\'' {
            let q = c;
            let mut j = i + 1;
            let mut tok = String::new();
            let mut closed = false;
            while j < n {
                if chars[j] == '\\' && j + 1 < n {
                    tok.push(chars[j]);
                    tok.push(chars[j + 1]);
                    j += 2;
                    continue;
                }
                if chars[j] == q {
                    closed = true;
                    break;
                }
                tok.push(chars[j]);
                j += 1;
            }
            if closed {
                out.push(tok);
                i = j + 1;
                if starts_sep(i) {
                    i += sepc.len();
                }
                continue;
            }
        }
        // read until separator
        let mut tok = String::new();
        while i < n && !starts_sep(i) {
            tok.push(chars[i]);
            i += 1;
        }
        out.push(tok);
        if starts_sep(i) {
            i += sepc.len();
        }
    }
    out.into_iter().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
}

pub fn build_parse_regex(pattern: &str) -> (regex::Regex, usize) {
    let mut re = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut count = 0;
    for (i, c) in chars.iter().enumerate() {
        if *c == '*' {
            count += 1;
            if i + 1 == chars.len() {
                re.push_str("(.*)");
            } else {
                re.push_str("(.*?)");
            }
        } else if c.is_whitespace() {
            re.push_str(r"\s");
        } else {
            re.push_str(&regex::escape(&c.to_string()));
        }
    }
    (regex::RegexBuilder::new(&re).dot_matches_new_line(true).build().unwrap(), count)
}

pub enum RowOp {
    Json(Option<Expr>),
    Logfmt(Option<Expr>),
    Split { from: Option<Expr>, sep: String, out: String },
    Parse { re: regex::Regex, fields: Vec<String>, from: Option<Expr>, nodrop: bool, noconvert: bool },
    ParseRegex { re: regex::Regex, from: Option<Expr>, nodrop: bool, noconvert: bool },
    Fields { mode: FieldMode, fields: Vec<String> },
    Where(Expr),
    FieldExpr { expr: Expr, name: String },
    Timeslice { expr: Expr, dur: chrono::TimeDelta, name: String },
    Total { expr: Expr, name: String, total: f64 },
    Limit { n: i64, seen: i64 },
}

fn conv(s: &str, noconvert: bool) -> Value {
    if noconvert {
        Value::Str(s.to_string())
    } else {
        Value::from_string(s)
    }
}

impl RowOp {
    pub fn apply(&mut self, mut rec: Record) -> RowResult {
        match self {
            RowOp::Json(from) => {
                let input = match get_input(from, &rec) {
                    Ok(Some(s)) => s,
                    Ok(None) => return RowResult::Drop,
                    Err(e) => return RowResult::Err(e),
                };
                match serde_json::from_str::<serde_json::Value>(&input) {
                    Ok(serde_json::Value::Object(m)) => {
                        for (k, v) in m.iter() {
                            rec.data.insert(k.clone(), Value::from_json(v));
                        }
                        RowResult::Keep(rec)
                    }
                    Ok(_) => RowResult::Keep(rec),
                    Err(_) => RowResult::Err(format!("Expected JSON, found {}", input)),
                }
            }
            RowOp::Logfmt(from) => {
                let input = match get_input(from, &rec) {
                    Ok(Some(s)) => s,
                    Ok(None) => return RowResult::Drop,
                    Err(e) => return RowResult::Err(e),
                };
                for (k, v) in logfmt_parse(&input) {
                    let val = match v {
                        Some(s) => Value::from_string(&s),
                        None => Value::None,
                    };
                    rec.data.insert(k, val);
                }
                RowResult::Keep(rec)
            }
            RowOp::Split { from, sep, out } => {
                let input = match get_input(from, &rec) {
                    Ok(Some(s)) => s,
                    Ok(None) => return RowResult::Drop,
                    Err(e) => return RowResult::Err(e),
                };
                let parts: Vec<Value> = split_quoted(&input, sep).iter().map(|s| Value::from_string(s)).collect();
                rec.data.insert(out.clone(), Value::Array(parts));
                RowResult::Keep(rec)
            }
            RowOp::Parse { re, fields, from, nodrop, noconvert } => {
                let input = match get_input(from, &rec) {
                    Ok(Some(s)) => s,
                    Ok(None) => return RowResult::Drop,
                    Err(e) => return RowResult::Err(e),
                };
                let t = input.trim();
                match re.captures(t) {
                    Some(caps) => {
                        for (i, f) in fields.iter().enumerate() {
                            let v = caps.get(i + 1).map(|m| conv(m.as_str(), *noconvert)).unwrap_or(Value::None);
                            rec.data.insert(f.clone(), v);
                        }
                        RowResult::Keep(rec)
                    }
                    None => {
                        if *nodrop {
                            for f in fields.iter() {
                                rec.data.insert(f.clone(), Value::None);
                            }
                            RowResult::Keep(rec)
                        } else {
                            RowResult::Drop
                        }
                    }
                }
            }
            RowOp::ParseRegex { re, from, nodrop, noconvert } => {
                let input = match get_input(from, &rec) {
                    Ok(Some(s)) => s,
                    Ok(None) => return RowResult::Drop,
                    Err(e) => return RowResult::Err(e),
                };
                let t = input.trim();
                match re.captures(t) {
                    Some(caps) => {
                        for name in re.capture_names().flatten() {
                            let v = caps.name(name).map(|m| conv(m.as_str(), *noconvert)).unwrap_or(Value::None);
                            rec.data.insert(name.to_string(), v);
                        }
                        RowResult::Keep(rec)
                    }
                    None => {
                        if *nodrop {
                            for name in re.capture_names().flatten() {
                                rec.data.insert(name.to_string(), Value::None);
                            }
                            RowResult::Keep(rec)
                        } else {
                            RowResult::Drop
                        }
                    }
                }
            }
            RowOp::Fields { mode, fields } => {
                match mode {
                    FieldMode::Only => {
                        rec.data.retain(|k, _| fields.contains(k));
                    }
                    FieldMode::Except => {
                        rec.data.retain(|k, _| !fields.contains(k));
                    }
                }
                RowResult::Keep(rec)
            }
            RowOp::Where(e) => match eval(e, &rec.data) {
                Ok(Value::Bool(true)) => RowResult::Keep(rec),
                Ok(Value::Bool(false)) => RowResult::Drop,
                Ok(other) => RowResult::Err(format!("Expected boolean, found {}", other)),
                Err(EvalError(m)) => RowResult::Err(m),
            },
            RowOp::FieldExpr { expr, name } => match eval(expr, &rec.data) {
                Ok(v) => {
                    rec.data.insert(name.clone(), v);
                    RowResult::Keep(rec)
                }
                Err(EvalError(m)) => RowResult::Err(m),
            },
            RowOp::Timeslice { expr, dur, name } => match eval(expr, &rec.data) {
                Ok(Value::DateTime(d)) => {
                    use chrono::DurationRound;
                    match d.duration_trunc(*dur) {
                        Ok(t) => {
                            rec.data.insert(name.clone(), Value::DateTime(t));
                            RowResult::Keep(rec)
                        }
                        Err(e) => RowResult::Err(format!("Duration is not valid for timeslice: {:?}", e)),
                    }
                }
                Ok(other) => RowResult::Err(format!(
                    "Expected date, found '{}'.  Use parseDate() to convert a value to a date",
                    other
                )),
                Err(EvalError(m)) => RowResult::Err(m),
            },
            RowOp::Total { expr, name, total } => {
                if let Ok(v) = eval(expr, &rec.data) {
                    if let Some(n) = v.as_number() {
                        *total += n.as_f64();
                    }
                }
                rec.data.insert(name.clone(), Value::from_float(*total));
                RowResult::Keep(rec)
            }
            RowOp::Limit { n, seen } => {
                if *seen >= *n {
                    return RowResult::Drop;
                }
                *seen += 1;
                RowResult::Keep(rec)
            }
        }
    }

    pub fn limit_done(&self) -> bool {
        match self {
            RowOp::Limit { n, seen } => *seen >= *n,
            _ => false,
        }
    }
}

// ------------------------------------------------------------- aggregates

pub struct Frame {
    pub columns: Vec<String>,
    pub rows: Vec<Data>,
}

enum AggState {
    Count(i64),
    Sum(Option<crate::value::Num>),
    Min(Option<Value>),
    Max(Option<Value>),
    Avg(f64, i64),
    Pct(Ckms),
    Distinct(HashSet<Value>),
}

fn new_state(f: &AggFn) -> AggState {
    match f {
        AggFn::Count(_) => AggState::Count(0),
        AggFn::Sum(_) => AggState::Sum(None),
        AggFn::Min(_) => AggState::Min(None),
        AggFn::Max(_) => AggState::Max(None),
        AggFn::Avg(_) => AggState::Avg(0.0, 0),
        AggFn::Pct(_, _) => AggState::Pct(Ckms::new(0.001)),
        AggFn::CountDistinct(_) => AggState::Distinct(HashSet::new()),
    }
}

fn update_state(st: &mut AggState, f: &AggFn, data: &Data) {
    use crate::value::Num;
    match (st, f) {
        (AggState::Count(c), AggFn::Count(cond)) => match cond {
            None => *c += 1,
            Some(e) => {
                if let Ok(Value::Bool(true)) = eval(e, data) {
                    *c += 1
                }
            }
        },
        (AggState::Sum(s), AggFn::Sum(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    *s = Some(match (*s, n) {
                        (None, n) => n,
                        (Some(Num::Int(a)), Num::Int(b)) => Num::Int(a.wrapping_add(b)),
                        (Some(a), b) => Num::Float(a.as_f64() + b.as_f64()),
                    });
                }
            }
        }
        (AggState::Min(m), AggFn::Min(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    let nv = n.to_value();
                    let replace = match m {
                        None => true,
                        Some(cur) => nv.partial_compare(cur) == Some(std::cmp::Ordering::Less),
                    };
                    if replace {
                        *m = Some(nv);
                    }
                }
            }
        }
        (AggState::Max(m), AggFn::Max(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    let nv = n.to_value();
                    let replace = match m {
                        None => true,
                        Some(cur) => nv.partial_compare(cur) == Some(std::cmp::Ordering::Greater),
                    };
                    if replace {
                        *m = Some(nv);
                    }
                }
            }
        }
        (AggState::Avg(s, c), AggFn::Avg(e)) => {
            if let Ok(v) = eval(e, data) {
                if let Some(n) = v.as_number() {
                    *s += n.as_f64();
                    *c += 1;
                }
            }
        }
