            }
        }
        _ => {}
    }
}

fn finish_state(st: &AggState, f: &AggFn) -> Value {
    match (st, f) {
        (AggState::Count(c), _) => Value::Int(*c),
        (AggState::Sum(s), _) => match s {
            None => Value::Int(0),
            Some(n) => n.to_value(),
        },
        (AggState::Min(m), _) | (AggState::Max(m), _) => m.clone().unwrap_or(Value::None),
        (AggState::Avg(s, c), _) => Value::from_float(*s / *c as f64),
        (AggState::Pct(ck), AggFn::Pct(q, _)) => match ck.query(*q) {
            Some(v) => Value::from_float(v),
            None => Value::None,
        },
        (AggState::Distinct(set), _) => Value::Int(set.len() as i64),
        _ => Value::None,
    }
}

pub struct Grouper {
    aggs: Vec<Aggregate>,
    by: Vec<(String, Expr)>,
    groups: HashMap<Vec<Value>, Vec<AggState>>,
    order: Vec<Vec<Value>>,
}

impl Grouper {
    pub fn new(aggs: Vec<Aggregate>, by: Vec<(String, Expr)>) -> Grouper {
        Grouper { aggs, by, groups: HashMap::new(), order: vec![] }
    }

    pub fn add(&mut self, data: &Data) {
        let key: Vec<Value> = self.by.iter().map(|(_, e)| eval(e, data).unwrap_or(Value::None)).collect();
        if !self.groups.contains_key(&key) {
            let states = self.aggs.iter().map(|a| new_state(&a.func)).collect();
            self.groups.insert(key.clone(), states);
            self.order.push(key.clone());
        }
        let states = self.groups.get_mut(&key).unwrap();
        for (st, a) in states.iter_mut().zip(self.aggs.iter()) {
            update_state(st, &a.func, data);
        }
    }

    pub fn finish(&self) -> Frame {
        let mut columns: Vec<String> = self.by.iter().map(|(n, _)| n.clone()).collect();
        for a in &self.aggs {
            columns.push(a.name.clone());
        }
        let mut rows: Vec<Data> = vec![];
        let mut keys = self.order.clone();
        if self.by.is_empty() && keys.is_empty() {
            keys.push(vec![]);
        }
        for k in keys.iter() {
            let mut d = Data::new();
            for (i, (n, _)) in self.by.iter().enumerate() {
                d.insert(n.clone(), k[i].clone());
            }
            let fresh;
            let states = match self.groups.get(k) {
                Some(s) => s,
                None => {
                    fresh = self.aggs.iter().map(|a| new_state(&a.func)).collect::<Vec<_>>();
                    &fresh
                }
            };
            for (st, a) in states.iter().zip(self.aggs.iter()) {
                d.insert(a.name.clone(), finish_state(st, &a.func));
            }
            rows.push(d);
        }
        let agg_names: Vec<String> = self.aggs.iter().map(|a| a.name.clone()).collect();
        let key_names: Vec<String> = self.by.iter().map(|(n, _)| n.clone()).collect();
        rows.sort_by(|a, b| {
            for n in &agg_names {
                let va = a.get(n).unwrap_or(&Value::None);
                let vb = b.get(n).unwrap_or(&Value::None);
                let o = vb.total_cmp(va);
                if o != std::cmp::Ordering::Equal {
                    return o;
                }
            }
            for n in &key_names {
                let va = a.get(n).unwrap_or(&Value::None);
                let vb = b.get(n).unwrap_or(&Value::None);
                let o = va.total_cmp(vb);
                if o != std::cmp::Ordering::Equal {
                    return o;
                }
            }
            std::cmp::Ordering::Equal
        });
        Frame { columns, rows }
    }
}

pub fn sort_frame(frame: &mut Frame, exprs: &[Expr], desc: bool) {
    let cols = frame.columns.clone();
    let mut keyed: Vec<(Vec<Value>, Data)> = frame
        .rows
        .drain(..)
        .map(|d| {
            let k: Vec<Value> = exprs.iter().map(|e| eval(e, &d).unwrap_or(Value::None)).collect();
            (k, d)
        })
        .collect();
    keyed.sort_by(|(ka, a), (kb, b)| {
        for (x, y) in ka.iter().zip(kb.iter()) {
            let o = x.total_cmp(y);
            if o != std::cmp::Ordering::Equal {
                return if desc { o.reverse() } else { o };
            }
        }
        for c in &cols {
            let va = a.get(c).unwrap_or(&Value::None);
            let vb = b.get(c).unwrap_or(&Value::None);
            let o = va.total_cmp(vb);
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        std::cmp::Ordering::Equal
    });
    frame.rows = keyed.into_iter().map(|(_, d)| d).collect();
}
