pub fn validate(fmt: &str) -> Result<(), FmtError> {
    format(fmt, &|_| None).map(|_| ())
}

pub fn format(fmt: &str, lookup: &dyn Fn(&str) -> Option<String>) -> Result<String, FmtError> {
    let chars: Vec<char> = fmt.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    let n = chars.len();
    while i < n {
        let c = chars[i];
        if c == '{' {
            if i + 1 < n && chars[i + 1] == '{' {
                out.push('{');
                i += 2;
                continue;
            }
            let mut j = i + 1;
            while j < n && chars[j] != '}' {
                j += 1;
            }
            if j >= n {
                return Err(FmtError::Invalid("Expected '}' before end of string".to_string()));
            }
            let inner: String = chars[i + 1..j].iter().collect();
            let (name, spec) = match inner.find(':') {
                Some(k) => (inner[..k].to_string(), inner[k + 1..].to_string()),
                None => (inner.clone(), String::new()),
            };
            if name.is_empty() {
                return Err(FmtError::Invalid("must specify identifier".to_string()));
            }
            let val = lookup(&name).unwrap_or_else(|| "None".to_string());
            out.push_str(&format_str(&val, &spec)?);
            i = j + 1;
        } else if c == '}' {
            if i + 1 < n && chars[i + 1] == '}' {
                out.push('}');
                i += 2;
                continue;
            }
            return Err(FmtError::Invalid("Single '}' encountered in format string".to_string()));
        } else {
            out.push(c);
            i += 1;
        }
    }
    Ok(out)
}

fn format_str(s: &str, spec: &str) -> Result<String, FmtError> {
    let sc: Vec<char> = spec.chars().collect();
    let mut i = 0;
    let mut fill = ' ';
    let mut align: Option<char> = None;
    let is_align = |c: char| c == '<' || c == '>' || c == '^' || c == '=';
    if sc.len() >= 2 && is_align(sc[1]) {
        fill = sc[0];
        align = Some(sc[1]);
        i = 2;
    } else if !sc.is_empty() && is_align(sc[0]) {
        align = Some(sc[0]);
        i = 1;
    }
    let mut sign = false;
    if i < sc.len() && (sc[i] == '+' || sc[i] == '-' || sc[i] == ' ') {
        sign = true;
        i += 1;
    }
    let mut alternate = false;
    if i < sc.len() && sc[i] == '#' {
        alternate = true;
        i += 1;
    }
    if i < sc.len() && sc[i] == '0' {
        if align.is_none() {
            fill = '0';
            align = Some('=');
        }
        i += 1;
    }
    let ws = i;
    while i < sc.len() && sc[i].is_ascii_digit() {
        i += 1;
    }
    let width: Option<usize> = if i > ws { sc[ws..i].iter().collect::<String>().parse().ok() } else { None };
    let mut thousands = false;
    if i < sc.len() && sc[i] == ',' {
        thousands = true;
        i += 1;
    }
    let mut precision: Option<usize> = None;
    if i < sc.len() && sc[i] == '.' {
        i += 1;
        let ps = i;
        while i < sc.len() && sc[i].is_ascii_digit() {
            i += 1;
        }
        precision = sc[ps..i].iter().collect::<String>().parse().ok();
    }
    let ty: Option<char> = if i < sc.len() { Some(sc[i]) } else { None };
    if i + 1 < sc.len() {
        return Err(FmtError::Invalid(format!("Invalid format string at {:?}", sc[i + 1..].iter().collect::<String>())));
    }
    if !(ty.is_none() || ty == Some('s')) {
        return Err(FmtError::TypeError(format!("Unknown format code {:?} for object of type 'str'", ty)));
    }
    if alternate {
        return Err(FmtError::TypeError("Alternate form (#) not allowed in string format specifier".to_string()));
    }
    if thousands {
        return Err(FmtError::TypeError("Cannot specify ',' with 's'.".to_string()));
    }
    if sign {
        return Err(FmtError::TypeError("Sign not allowed in string format specifier".to_string()));
    }
    if align == Some('=') {
        return Err(FmtError::Invalid("sign aware zero padding and Align '=' not yet supported".to_string()));
    }
    let mut v: Vec<char> = s.chars().collect();
    if let Some(p) = precision {
        v.truncate(p);
    }
    let len = v.len();
    let body: String = v.into_iter().collect();
    match width {
        Some(w) if w > len => {
            let pad = w - len;
            let fs = |k: usize| -> String { std::iter::repeat(fill).take(k).collect() };
            Ok(match align.unwrap_or('<') {
                '>' => format!("{}{}", fs(pad), body),
                '^' => format!("{}{}{}", fs(pad / 2), body, fs(pad - pad / 2)),
                _ => format!("{}{}", body, fs(pad)),
            })
        }
        _ => Ok(body),
    }
}
