use crate::eval::Data;
use crate::ops::{Frame, Record};
use crate::value::Value;
use std::io::Write;

#[derive(Clone)]
pub enum OutputMode {
    Legacy,
    Json,
    Logfmt,
    Format(String),
}

pub struct RowRenderer {
    mode: OutputMode,
    columns: Vec<(String, usize)>, // key, value width
}

fn clen(s: &str) -> usize {
    s.chars().count()
}

impl RowRenderer {
    pub fn new(mode: OutputMode) -> RowRenderer {
        RowRenderer { mode, columns: vec![] }
    }

    pub fn render(&mut self, rec: &Record) -> String {
        match &self.mode {
            OutputMode::Legacy => self.legacy(rec),
            OutputMode::Json => json_object(&rec.data),
            OutputMode::Logfmt => logfmt_line(&rec.data),
            OutputMode::Format(f) => format_line(f, &rec.data),
        }
    }

    fn legacy(&mut self, rec: &Record) -> String {
        if rec.data.is_empty() && self.columns.is_empty() {
            return rec.raw.clone().unwrap_or_default();
        }
        for (k, v) in rec.data.iter() {
            let vs = v.to_string();
            let vl = clen(&vs);
            match self.columns.iter_mut().find(|(c, _)| c == k) {
                Some((_, w)) => {
                    if vl > *w + 4 {
                        *w = vl;
                    }
                }
                None => {
                    let kl = clen(k);
                    self.columns.push((k.clone(), kl.max(vl)));
                }
            }
        }
        let mut line = String::new();
        for (k, w) in self.columns.iter() {
            let total = clen(k) + 3 + *w + 8;
            match rec.data.get(k) {
                Some(v) => {
                    let cell = format!("[{}={}]", k, v);
                    let cl = clen(&cell);
                    line.push_str(&cell);
                    if total > cl {
                        line.push_str(&" ".repeat(total - cl));
                    }
                }
                None => line.push_str(&" ".repeat(total)),
            }
        }
        line.trim().to_string()
    }
}

pub fn json_object(d: &Data) -> String {
    let mut m = serde_json::Map::new();
    for (k, v) in d.iter() {
        m.insert(k.clone(), v.to_json());
    }
    serde_json::to_string(&serde_json::Value::Object(m)).unwrap()
}

pub fn logfmt_line(d: &Data) -> String {
    let parts: Vec<String> = d.iter().map(|(k, v)| format!("{}={}", k, v)).collect();
    parts.join(" ")
}

pub fn format_line(f: &str, d: &Data) -> String {
    crate::strfmt::format(f, &|k| d.get(k).map(|v| v.to_string())).unwrap_or_default()
}

pub fn render_frame(frame: &Frame, mode: &OutputMode, out: &mut dyn Write) -> std::io::Result<()> {
    match mode {
        OutputMode::Legacy => {
            if frame.rows.is_empty() {
                writeln!(out, "No data")?;
                return Ok(());
            }
            let none = Value::None;
            let cells: Vec<Vec<String>> = frame
                .rows
                .iter()
                .map(|r| frame.columns.iter().map(|c| r.get(c).unwrap_or(&none).to_string()).collect())
                .collect();
            let mut widths: Vec<usize> = frame.columns.iter().map(|c| clen(c)).collect();
            for row in cells.iter() {
                for (i, c) in row.iter().enumerate() {
                    widths[i] = widths[i].max(clen(c));
                }
            }
            let pad = |s: &str, w: usize| -> String {
                let l = clen(s);
                format!("{}{}", s, " ".repeat(w + 8 - l))
            };
            let header: String = frame.columns.iter().enumerate().map(|(i, c)| pad(c, widths[i])).collect();
            writeln!(out, "{}", header.trim())?;
            let total: usize = widths.iter().map(|w| w + 8).sum();
            writeln!(out, "{}", "-".repeat(total))?;
            for row in cells.iter() {
                let line: String = row.iter().enumerate().map(|(i, c)| pad(c, widths[i])).collect();
                writeln!(out, "{}", line.trim())?;
            }
        }
        OutputMode::Json => {
            let mut s = String::from("[");
            for (i, r) in frame.rows.iter().enumerate() {
                if i > 0 {
                    s.push(',');
                }
                s.push('{');
                for (j, c) in frame.columns.iter().enumerate() {
                    if j > 0 {
                        s.push(',');
                    }
                    s.push_str(&serde_json::to_string(c).unwrap());
                    s.push(':');
                    let v = r.get(c).cloned().unwrap_or(Value::None);
                    s.push_str(&serde_json::to_string(&v.to_json()).unwrap());
                }
                s.push('}');
            }
            s.push(']');
            writeln!(out, "{}", s)?;
        }
        OutputMode::Logfmt => {
            for r in frame.rows.iter() {
                writeln!(out, "{}", logfmt_line(r))?;
            }
        }
        OutputMode::Format(f) => {
            for r in frame.rows.iter() {
                writeln!(out, "{}", format_line(f, r))?;
            }
        }
    }
    Ok(())
}
