struct LoadedAlias {
    keyword: String,
    template: String,
}

fn load_alias_dir(dir: &std::path::Path, out: &mut Vec<LoadedAlias>) -> std::io::Result<()> {
    let mut entries: Vec<std::path::PathBuf> = std::fs::read_dir(dir)?.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            continue;
        }
        let contents = match std::fs::read_to_string(&path) {
            Ok(c) => c,
            Err(_) => continue,
        };
        match contents.parse::<toml::Table>() {
            Ok(t) => {
                let kw = t.get("keyword").and_then(|v| v.as_str()).map(|s| s.to_string());
                let tp = t.get("template").and_then(|v| v.as_str()).map(|s| s.to_string());
                match (kw, tp) {
                    (Some(k), Some(tp)) => out.push(LoadedAlias { keyword: k, template: tp }),
                    (None, _) => {
                        eprintln!(
                            "warning: invalid alias: missing field `keyword`\n--> {}\n |\n |",
                            path.display()
                        );
                    }
                    (_, None) => {
                        eprintln!(
                            "warning: invalid alias: missing field `template`\n--> {}\n |\n |",
                            path.display()
                        );
                    }
                }
            }
            Err(e) => {
                eprintln!("warning: invalid alias: {}\n--> {}\n |\n |", e, path.display());
            }
        }
    }
    Ok(())
}

enum Stage {
    Row(RowOp),
    LimitLast(usize),
    Agg(Vec<Aggregate>, Vec<(String, Expr)>),
    Sort(Vec<Expr>, bool),
}

fn is_barrier(s: &Stage) -> bool {
    !matches!(s, Stage::Row(_))
}

fn check_expr(e: &Expr) {
    if let Err(m) = eval::check_functions(e) {
        fail(&m);
    }
}

fn build_stage(op: Op) -> Stage {
    match op {
        Op::Json { from } => {
            if let Some(f) = &from {
                check_expr(f);
            }
            Stage::Row(RowOp::Json(from))
        }
        Op::Logfmt { from } => {
            if let Some(f) = &from {
                check_expr(f);
            }
            Stage::Row(RowOp::Logfmt(from))
        }
        Op::Split { from, sep, out } => {
            let out = match (&out, &from) {
                (Some(o), _) => o.clone(),
                (None, Some(Expr::Column { head, .. })) => head.clone(),
                _ => "_split".to_string(),
            };
            Stage::Row(RowOp::Split { from, sep, out })
        }
        Op::Parse { pattern, fields, from, nodrop, noconvert, .. } => {
            let (re, count) = ops::build_parse_regex(&pattern);
            if count != fields.len() {
                fail(&format!(
                    "Wrong number of patterns for parse. Pattern has {} but {} were extracted",
                    count,
                    fields.len()
                ));
            }
            Stage::Row(RowOp::Parse { re, fields, from, nodrop, noconvert })
        }
        Op::ParseRegex { regex, from, nodrop, noconvert } => Stage::Row(RowOp::ParseRegex { re: regex, from, nodrop, noconvert }),
        Op::Fields { mode, fields } => Stage::Row(RowOp::Fields { mode, fields }),
        Op::Where(e) => {
            check_expr(&e);
            Stage::Row(RowOp::Where(e))
        }
        Op::Limit(n) => {
            if n > 0 {
                Stage::Row(RowOp::Limit { n, seen: 0 })
            } else {
                Stage::LimitLast((-n) as usize)
            }
        }
        Op::FieldExpr { expr, name } => {
            check_expr(&expr);
            Stage::Row(RowOp::FieldExpr { expr, name })
        }
        Op::Timeslice { expr, dur, name } => {
            check_expr(&expr);
            match dur {
                Some(d) => Stage::Row(RowOp::Timeslice { expr, dur: d, name }),
                None => fail("Expected a duration for the timeslice (e.g. 1h)"),
            }
        }
        Op::Total { expr, name } => {
            check_expr(&expr);
            Stage::Row(RowOp::Total { expr, name, total: 0.0 })
        }
        Op::Sort { exprs, desc } => {
            for e in &exprs {
                check_expr(e);
            }
            Stage::Sort(exprs, desc)
        }
        Op::Agg { aggs, by } => {
            for (_, e) in &by {
                check_expr(e);
            }
            Stage::Agg(aggs, by)
        }
    }
}

fn keyword_regex(text: &str) -> regex::Regex {
    let mut re = String::new();
    for c in text.chars() {
        if c == '*' {
            re.push_str(".*");
        } else {
            re.push_str(&regex::escape(&c.to_string()));
        }
    }
    regex::RegexBuilder::new(&re).case_insensitive(true).build().unwrap()
}

enum Matcher {
    And(Vec<Matcher>),
    Or(Vec<Matcher>),
    Not(Box<Matcher>),
    Regex(regex::Regex),
    Contains(String),
    All,
}

fn build_matcher(s: &Search) -> Matcher {
    match s {
        Search::And(v) => Matcher::And(v.iter().map(build_matcher).collect()),
        Search::Or(v) => Matcher::Or(v.iter().map(build_matcher).collect()),
        Search::Not(x) => Matcher::Not(Box::new(build_matcher(x))),
        Search::Keyword { text, quoted } => {
            if *quoted {
                Matcher::Contains(text.clone())
            } else {
                Matcher::Regex(keyword_regex(text))
            }
        }
        Search::MatchAll => Matcher::All,
    }
}

fn matches(m: &Matcher, line: &str) -> bool {
    match m {
        Matcher::And(v) => v.iter().all(|x| matches(x, line)),
        Matcher::Or(v) => v.iter().any(|x| matches(x, line)),
        Matcher::Not(x) => !matches(x, line),
        Matcher::Regex(r) => r.is_match(line),
        Matcher::Contains(s) => line.contains(s.as_str()),
        Matcher::All => true,
    }
}

fn frame_from_records(recs: Vec<Record>) -> Frame {
    let mut columns: Vec<String> = vec![];
    for r in recs.iter() {
        for k in r.data.keys() {
            if !columns.contains(k) {
                columns.push(k.clone());
            }
        }
    }
    Frame { columns, rows: recs.into_iter().map(|r| r.data).collect() }
}

fn print_err(msg: &str) {
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = writeln!(h, "error: {}", msg);
}

enum Batch {
    Rows(Vec<Record>),
    Frame(Frame),
}

fn apply_row_op_frame(op: &mut RowOp, frame: Frame) -> Frame {
    let old_cols = frame.columns.clone();
    let mut rows = vec![];
    for d in frame.rows.into_iter() {
        match op.apply(Record { data: d, raw: None }) {
            RowResult::Keep(r) => rows.push(r.data),
            RowResult::Drop => {}
            RowResult::Err(m) => print_err(&m),
        }
    }
    let mut columns: Vec<String> = vec![];
    for c in old_cols.iter() {
        if rows.iter().any(|r| r.contains_key(c)) || rows.is_empty() {
            columns.push(c.clone());
        }
    }
    for r in rows.iter() {
        for k in r.keys() {
            if !columns.contains(k) {
                columns.push(k.clone());
            }
        }
    }
    Frame { columns, rows }
}

fn main() {
    let matches = build_cli().get_matches();
    let query: Option<String> = matches.get_one::<String>("query").cloned();
    let file: Option<String> = matches.get_one::<String>("file").cloned();
    let format_m: Option<String> = matches.get_one::<String>("format").cloned();
    let output: Option<String> = matches.get_one::<String>("output").cloned();
    let alias_dir: Option<String> = matches.get_one::<String>("alias_dir").cloned();
    let no_alias = matches.get_flag("no_alias");

    // aliases
    let mut loaded: Vec<LoadedAlias> = vec![];
    if !no_alias {
        match &alias_dir {
            Some(d) => {
                if let Err(e) = load_alias_dir(std::path::Path::new(d), &mut loaded) {
                    fail(&e.to_string());
                }
            }
            None => {
                if let Ok(cwd) = std::env::current_dir() {
                    let mut cur: Option<&std::path::Path> = Some(cwd.as_path());
                    while let Some(dir) = cur {
                        let ad = dir.join(".agrind-aliases");
                        if ad.is_dir() {
                            let _ = load_alias_dir(&ad, &mut loaded);
                        }
                        cur = dir.parent();
                    }
                }
            }
        }
    }
    for (k, t) in BUILTIN_ALIASES {
        loaded.push(LoadedAlias { keyword: k.to_string(), template: t.to_string() });
    }

    let query = match query {
        Some(q) => q,
        None => fail("MissingQuery"),
    };

    let mode = match (&format_m, &output) {
        (Some(_), Some(_)) => fail("CantSupplyBoth"),
        (Some(f), None) => OutputMode::Format(f.clone()),
        (None, Some(o)) => match o.as_str() {
            "legacy" => OutputMode::Legacy,
            "json" => OutputMode::Json,
            "logfmt" => OutputMode::Logfmt,
            other if other.starts_with("format") => match other.strip_prefix("format=") {
                Some(f) if !f.is_empty() => OutputMode::Format(f.to_string()),
                _ => fail("InvalidFormatString"),
            },
            other => fail(&format!(
                "InvalidOutputMode {{ choice: {:?}, choices: \"legacy, json, logfmt, format\" }}",
                other
            )),
        },
        (None, None) => OutputMode::Legacy,
    };

    // parse aliases' templates
    let mut alias_defs: Vec<AliasDef> = vec![];
    let mut alias_ops: Vec<(String, Vec<Op>)> = vec![];
    for a in loaded.iter() {
        if alias_defs.iter().any(|d| d.keyword == a.keyword) {
            continue;
        }
        let empty: Vec<AliasDef> = vec![];
        let no_alias_fn = |_: &str| -> Option<Vec<Op>> { None };
        let mut p = Parser::new(&a.template, &empty, &no_alias_fn);
        let ops = p.parse_pipeline_only();
        if !p.errors.is_empty() {
            let stderr = std::io::stderr();
            let mut h = stderr.lock();
            for d in p.errors.iter() {
                let _ = write!(h, "{}", d.render(&a.template));
            }
        }
        alias_defs.push(AliasDef { keyword: a.keyword.clone(), template: a.template.clone() });
        alias_ops.push((a.keyword.clone(), ops));
    }
    let lookup = |k: &str| -> Option<Vec<Op>> { alias_ops.iter().find(|(n, _)| n == k).map(|(_, o)| o.clone()) };

    let mut parser = Parser::new(&query, &alias_defs, &lookup);
    let parsed = parser.parse_query();
    if !parser.errors.is_empty() || parsed.is_none() {
        let stderr = std::io::stderr();
        let mut h = stderr.lock();
        for d in parser.errors.iter() {
            let _ = write!(h, "{}", d.render(&query));
        }
        drop(h);
        fail("Failed to parse query");
    }
    if let Some((d, msg)) = parser.sem_errors.first() {
        eprint!("{}", d.render(&query));
        fail(msg);
    }
    let (search, ops) = parsed.unwrap();
    let mut stages: Vec<Stage> = ops.into_iter().map(build_stage).collect();

    if let OutputMode::Format(f) = &mode {
        if let Err(e) = strfmt::validate(f) {
            fail(&format!("{:?}", e));
        }
    }

    let reader: Box<dyn BufRead> = match &file {
        Some(f) => match std::fs::File::open(f) {
            Ok(fh) => Box::new(std::io::BufReader::new(fh)),
            Err(e) => fail(&format!("{:?}", e)),
        },
        None => Box::new(std::io::BufReader::new(std::io::stdin())),
    };

    let matcher = build_matcher(&search);
    let first_barrier = stages.iter().position(is_barrier).unwrap_or(stages.len());
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut renderer = RowRenderer::new(mode.clone());
    let mut collected: Vec<Record> = vec![];
    let mut grouper: Option<Grouper> = None;
    let mut last_buf: std::collections::VecDeque<Record> = std::collections::VecDeque::new();
    if let Some(Stage::Agg(aggs, by)) = stages.get(first_barrier) {
        grouper = Some(Grouper::new(aggs.clone(), by.clone()));
    }
    let mut reader = reader;
    let mut buf: Vec<u8> = Vec::new();
    'outer: loop {
        buf.clear();
        match reader.read_until(b'\n', &mut buf) {
            Ok(0) => break,
            Ok(_) => {}
            Err(_) => break,
        }
        let line = String::from_utf8_lossy(&buf);
        let line = line.trim_end();
        if !matches(&matcher, line) {
            continue;
        }
        let mut rec = Record { data: Default::default(), raw: Some(line.to_string()) };
        let mut dropped = false;
        for st in stages[..first_barrier].iter_mut() {
            if let Stage::Row(op) = st {
                match op.apply(rec) {
                    RowResult::Keep(r) => rec = r,
                    RowResult::Drop => {
                        dropped = true;
                        rec = Record { data: Default::default(), raw: None };
                        if op.limit_done() {
                            break 'outer;
                        }
                        break;
                    }
                    RowResult::Err(m) => {
                        print_err(&m);
                        dropped = true;
                        rec = Record { data: Default::default(), raw: None };
                        break;
                    }
                }
            }
        }
        if dropped {
            continue;
        }
        if first_barrier == stages.len() {
            let s = renderer.render(&rec);
            if writeln!(out, "{}", s).is_err() {
                std::process::exit(0);
            }
        } else {
            match &stages[first_barrier] {
                Stage::Agg(..) => grouper.as_mut().unwrap().add(&rec.data),
                Stage::LimitLast(n) => {
                    last_buf.push_back(rec);
                    if last_buf.len() > *n {
                        last_buf.pop_front();
                    }
                }
                _ => collected.push(rec),
            }
        }
        // stop early if a positive limit is exhausted
        let mut done = false;
        for st in stages[..first_barrier].iter() {
            if let Stage::Row(op) = st {
                if op.limit_done() {
                    done = true;
                }
            }
        }
        if done {
            break;
        }
    }

    if first_barrier < stages.len() {
        let mut batch = match &stages[first_barrier] {
            Stage::Agg(..) => Batch::Frame(grouper.take().unwrap().finish()),
            Stage::LimitLast(_) => Batch::Rows(last_buf.into_iter().collect()),
            Stage::Sort(exprs, desc) => {
                let mut f = frame_from_records(std::mem::take(&mut collected));
                ops::sort_frame(&mut f, exprs, *desc);
                Batch::Frame(f)
            }
            _ => unreachable!(),
        };
        for st in stages[first_barrier + 1..].iter_mut() {
            batch = match (batch, st) {
                (Batch::Rows(rs), Stage::Row(op)) => {
                    let mut kept = vec![];
                    for r in rs {
                        match op.apply(r) {
                            RowResult::Keep(r) => kept.push(r),
                            RowResult::Drop => {}
                            RowResult::Err(m) => print_err(&m),
                        }
                    }
                    Batch::Rows(kept)
                }
                (Batch::Rows(mut rs), Stage::LimitLast(n)) => {
                    let n = *n;
                    if rs.len() > n {
                        rs.drain(..rs.len() - n);
                    }
                    Batch::Rows(rs)
                }
                (Batch::Rows(rs), Stage::Agg(aggs, by)) => {
                    let mut g = Grouper::new(aggs.clone(), by.clone());
                    for r in rs.iter() {
                        g.add(&r.data);
                    }
                    Batch::Frame(g.finish())
                }
                (Batch::Rows(rs), Stage::Sort(exprs, desc)) => {
                    let mut f = frame_from_records(rs);
                    ops::sort_frame(&mut f, exprs, *desc);
                    Batch::Frame(f)
                }
                (Batch::Frame(f), Stage::Row(op)) => {
                    if let RowOp::Limit { n, .. } = op {
                        let mut f = f;
                        f.rows.truncate(*n as usize);
                        Batch::Frame(f)
                    } else {
                        Batch::Frame(apply_row_op_frame(op, f))
                    }
                }
                (Batch::Frame(mut f), Stage::LimitLast(n)) => {
                    let n = *n;
                    if f.rows.len() > n {
                        f.rows.drain(..f.rows.len() - n);
                    }
                    Batch::Frame(f)
                }
                (Batch::Frame(f), Stage::Agg(aggs, by)) => {
                    let mut g = Grouper::new(aggs.clone(), by.clone());
                    for r in f.rows.iter() {
                        g.add(r);
                    }
                    Batch::Frame(g.finish())
                }
                (Batch::Frame(mut f), Stage::Sort(exprs, desc)) => {
                    ops::sort_frame(&mut f, exprs, *desc);
                    Batch::Frame(f)
                }
            };
        }
        match batch {
            Batch::Rows(rs) => {
                for r in rs.iter() {
                    let s = renderer.render(r);
                    if writeln!(out, "{}", s).is_err() {
                        std::process::exit(0);
                    }
                }
            }
            Batch::Frame(f) => {
                let _ = render::render_frame(&f, &mode, &mut out);
            }
        }
    }
    let _ = out.flush();
}

impl<'a> Parser<'a> {
    pub fn parse_pipeline_only(&mut self) -> Vec<Op> {
        let mut ops = vec![];
        let mut p = self.ws(0);
        loop {
            match self.operator_pub(p) {
                OpResult::Ok(mut o, e) => {
                    ops.append(&mut o);
                    let e2 = self.ws(e);
                    if e2 >= self.src.len() || self.src.as_bytes()[e2] != b'|' {
                        break;
                    }
                    p = self.ws(e2 + 1);
                }
                OpResult::Fail => {
                    if self.errors.is_empty() {
                        self.generic_operator_error_pub(p);
                    }
                    let rest = &self.src[p..];
                    match rest.find('|') {
                        Some(i) => p = self.ws(p + i + 1),
                        None => break,
                    }
                }
            }
        }
        ops
    }
}
