                    if nextchar == '.' || is_num(nextchar) {
                        t.push(nextchar);
                    } else if is_word(nextchar) && t.ends_with('.') {
                        t.push(nextchar);
                        state = Some("a.");
                    } else {
                        charstack.push(nextchar);
                        break;
                    }
                }
                _ => break,
            }
        }
        let mut token = match token {
            Some(t) => t,
            None => {
                if eof && charstack.is_empty() {
                    break;
                }
                continue;
            }
        };
        if let Some(st) = state {
            if (st == "a." || st == "0.")
                && (seenletters || token.matches('.').count() > 1 || token.ends_with('.') || token.ends_with(','))
            {
                // split on [.,] keeping separators
                let mut parts: Vec<String> = vec![];
                let mut cur = String::new();
                for c in token.chars() {
                    if c == '.' || c == ',' {
                        parts.push(std::mem::take(&mut cur));
                        parts.push(c.to_string());
                    } else {
                        cur.push(c);
                    }
                }
                parts.push(cur);
                token = parts[0].clone();
                for p in parts.into_iter().skip(1) {
                    if !p.is_empty() {
                        tokenstack.push(p);
                    }
                }
            }
            if st == "0." && !token.contains('.') {
                token = token.replace(',', ".");
            }
        }
        out.push(token);
    }
    out
}

const JUMP: &[&str] = &[" ", ".", ",", ";", "-", "/", "'", "at", "on", "and", "ad", "m", "t", "of", "st", "nd", "rd", "th"];
const WEEKDAYS: &[&[&str]] = &[
    &["mon", "monday"],
    &["tue", "tuesday"],
    &["wed", "wednesday"],
    &["thu", "thursday"],
    &["fri", "friday"],
    &["sat", "saturday"],
    &["sun", "sunday"],
];
const MONTHS: &[&[&str]] = &[
    &["jan", "january"],
    &["feb", "february"],
    &["mar", "march"],
    &["apr", "april"],
    &["may", "may"],
    &["jun", "june"],
    &["jul", "july"],
    &["aug", "august"],
    &["sep", "sept", "september"],
    &["oct", "october"],
    &["nov", "november"],
    &["dec", "december"],
];
const HMS: &[&[&str]] = &[&["h", "hour", "hours"], &["m", "minute", "minutes"], &["s", "second", "seconds"]];
const AMPM: &[&[&str]] = &[&["am", "a"], &["pm", "p"]];
const UTCZONE: &[&str] = &["UTC", "GMT", "Z", "z"];
const PERTAIN: &[&str] = &["of"];

fn lookup(table: &[&[&str]], s: &str) -> Option<usize> {
    let l = s.to_lowercase();
    table.iter().position(|names| names.contains(&l.as_str()))
}
fn jump(s: &str) -> bool {
    JUMP.contains(&s.to_lowercase().as_str())
}
fn weekday(s: &str) -> Option<usize> {
    lookup(WEEKDAYS, s)
}
fn month(s: &str) -> Option<usize> {
    lookup(MONTHS, s).map(|m| m + 1)
}
fn hms(s: &str) -> Option<usize> {
    lookup(HMS, s)
}
fn ampm(s: &str) -> Option<usize> {
    lookup(AMPM, s)
}
fn pertain(s: &str) -> bool {
    PERTAIN.contains(&s.to_lowercase().as_str())
}
fn utczone(s: &str) -> bool {
    UTCZONE.contains(&s)
}

#[derive(Default, Debug)]
struct Res {
    year: Option<i32>,
    month: Option<i32>,
    day: Option<i32>,
    weekday: Option<usize>,
    hour: Option<i32>,
    minute: Option<i32>,
    second: Option<i32>,
    nanosecond: Option<i64>,
    tzname: Option<String>,
    tzoffset: Option<i32>,
    ampm: Option<usize>,
    century_specified: bool,
}

impl Res {
    fn len(&self) -> usize {
        let mut n = 0;
        if self.year.is_some() {
            n += 1
        }
        if self.month.is_some() {
            n += 1
        }
        if self.day.is_some() {
            n += 1
        }
        if self.weekday.is_some() {
            n += 1
        }
        if self.hour.is_some() {
            n += 1
        }
        if self.minute.is_some() {
            n += 1
        }
        if self.second.is_some() {
            n += 1
        }
        if self.nanosecond.is_some() {
            n += 1
        }
        if self.tzname.is_some() {
            n += 1
        }
        if self.tzoffset.is_some() {
            n += 1
        }
        if self.ampm.is_some() {
            n += 1
        }
        n
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Label {
    Y,
    M,
    D,
}

#[derive(Default)]
struct Ymd {
    vals: Vec<i32>,
    century_specified: bool,
    dstridx: Option<usize>,
    mstridx: Option<usize>,
    ystridx: Option<usize>,
}

type PResult<T> = Result<T, String>;

fn days_in_month(year: i32, month: i32) -> PResult<i32> {
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Ok(31),
        4 | 6 | 9 | 11 => Ok(30),
        2 => Ok(if leap { 29 } else { 28 }),
        _ => Err("ImpossibleTimestamp(\"Invalid month\")".to_string()),
    }
}

impl Ymd {
    fn could_be_day(&self, value: i32) -> bool {
        if self.dstridx.is_some() {
            false
        } else if self.mstridx.is_none() {
            (1..=31).contains(&value)
        } else if self.ystridx.is_none() {
            let m = self.vals[self.mstridx.unwrap()];
            match days_in_month(2000, m) {
                Ok(d) => 1 <= value && value <= d,
                Err(_) => false,
            }
        } else {
            let m = self.vals[self.mstridx.unwrap()];
            let y = self.vals[self.ystridx.unwrap()];
            match days_in_month(y, m) {
                Ok(d) => 1 <= value && value <= d,
                Err(_) => false,
            }
        }
    }

    fn append(&mut self, val: i32, token: Option<&str>, label: Option<Label>) -> PResult<()> {
        let mut label = label;
        let is_y = match token {
            Some(t) => t.chars().count() > 2 && t.chars().all(|c| c.is_ascii_digit() || c == '.'),
            None => false,
        } || val > 100;
        if is_y {
            self.century_specified = true;
            match label {
                None | Some(Label::Y) => {}
                _ => return Err("YearMonthDayError(\"Invalid label\")".to_string()),
            }
            label = Some(Label::Y);
        }
        self.vals.push(val);
        match label {
            Some(Label::M) => {
                if self.mstridx.is_some() {
                    return Err("YearMonthDayError(\"Month already set\")".to_string());
                }
                self.mstridx = Some(self.vals.len() - 1);
            }
            Some(Label::D) => {
                if self.dstridx.is_some() {
                    return Err("YearMonthDayError(\"Day already set\")".to_string());
                }
                self.dstridx = Some(self.vals.len() - 1);
            }
            Some(Label::Y) => {
                if self.ystridx.is_some() {
                    return Err("YearMonthDayError(\"Year already set\")".to_string());
                }
                self.ystridx = Some(self.vals.len() - 1);
            }
            None => {}
        }
        Ok(())
    }

    fn resolve(&self) -> PResult<(Option<i32>, Option<i32>, Option<i32>)> {
        let len = self.vals.len();
        let mut strids: Vec<(char, usize)> = vec![];
        if let Some(i) = self.ystridx {
            strids.push(('y', i));
        }
        if let Some(i) = self.mstridx {
            strids.push(('m', i));
        }
        if let Some(i) = self.dstridx {
            strids.push(('d', i));
        }
        if (len == strids.len() && len > 0) || (len == 3 && strids.len() == 2) {
            if len == 3 && strids.len() == 2 {
                let used: Vec<usize> = strids.iter().map(|(_, i)| *i).collect();
                let missing = (0..3).find(|x| !used.contains(x)).unwrap();
                let keys: Vec<char> = strids.iter().map(|(k, _)| *k).collect();
                let key = ['y', 'm', 'd'].iter().find(|k| !keys.contains(k)).unwrap();
                strids.push((*key, missing));
            }
            let get = |k: char| strids.iter().find(|(kk, _)| *kk == k).map(|(_, i)| self.vals[*i]);
            return Ok((get('y'), get('m'), get('d')));
        }
        let (mut year, mut month, mut day) = (None, None, None);
        let mstridx = self.mstridx;
        let v = &self.vals;
        if len > 3 {
            return Err("YearMonthDayError(\"More than three YMD values\")".to_string());
        } else if len == 1 || (mstridx.is_some() && len == 2) {
            if let Some(m) = mstridx {
                month = Some(v[m]);
                if len > 1 {
                    let other = if m == 0 { v[1] } else { v[0] };
                    if other > 31 {
                        year = Some(other);
                    } else {
                        day = Some(other);
                    }
                }
            }
        } else if len == 2 {
            if v[0] > 31 {
                year = Some(v[0]);
                month = Some(v[1]);
            } else if v[1] > 31 {
                month = Some(v[0]);
                year = Some(v[1]);
            } else {
                month = Some(v[0]);
                day = Some(v[1]);
            }
        } else if len == 3 {
            match mstridx {
                Some(0) => {
                    if v[1] > 31 {
                        month = Some(v[0]);
                        year = Some(v[1]);
                        day = Some(v[2]);
                    } else {
                        month = Some(v[0]);
                        day = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
                Some(1) => {
                    if v[0] > 31 {
                        year = Some(v[0]);
                        month = Some(v[1]);
                        day = Some(v[2]);
                    } else {
                        day = Some(v[0]);
                        month = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
                Some(2) => {
                    if v[1] > 31 {
                        day = Some(v[0]);
                        year = Some(v[1]);
                        month = Some(v[2]);
                    } else {
                        year = Some(v[0]);
                        day = Some(v[1]);
                        month = Some(v[2]);
                    }
                }
                _ => {
                    if v[0] > 31 || self.ystridx == Some(0) {
                        year = Some(v[0]);
                        month = Some(v[1]);
                        day = Some(v[2]);
                    } else if v[0] > 12 {
                        day = Some(v[0]);
                        month = Some(v[1]);
                        year = Some(v[2]);
                    } else {
                        month = Some(v[0]);
                        day = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
            }
        }
        Ok((year, month, day))
    }
}

fn to_decimal(s: &str) -> Option<f64> {
    // decimal numbers: digits with optional single '.'
    if s.is_empty() {
        return None;
    }
    let mut dots = 0;
    for (i, c) in s.chars().enumerate() {
        if c == '.' {
            dots += 1;
        } else if c == '-' || c == '+' {
            if i != 0 {
                return None;
            }
        } else if !c.is_ascii_digit() {
            return None;
        }
    }
    if dots > 1 {
        return None;
    }
    if s == "." || s == "-" || s == "+" {
        return None;
    }
    s.parse::<f64>().ok()
}

fn parsems(s: &str) -> PResult<(i32, i64)> {
    match s.find('.') {
        None => Ok((s.parse::<i32>().map_err(|_| format!("InvalidNumeric({:?})", s))?, 0)),
        Some(i) => {
            let ip = &s[..i];
            let fp = &s[i + 1..];
            let iv = ip.parse::<i32>().map_err(|_| format!("InvalidNumeric({:?})", s))?;
            let mut f: String = fp.chars().take(9).collect();
            while f.len() < 9 {
                f.push('0');
            }
            let fv = f.parse::<i64>().map_err(|_| format!("InvalidNumeric({:?})", s))?;
            Ok((iv, fv))
        }
    }
}

fn parse_min_sec(value: f64) -> (i32, Option<i32>) {
    let minute = value.trunc() as i32;
    let rem = value % 1.0;
    let second = if rem != 0.0 { Some((60.0 * rem) as i32) } else { None };
    (minute, second)
}

fn find_hms_idx(idx: usize, tokens: &[String], allow_jump: bool) -> Option<usize> {
    let len_l = tokens.len();
    if idx + 1 < len_l && hms(&tokens[idx + 1]).is_some() {
        Some(idx + 1)
    } else if allow_jump && idx + 2 < len_l && tokens[idx + 1] == " " && hms(&tokens[idx + 2]).is_some() {
        Some(idx + 2)
    } else if idx > 0 && hms(&tokens[idx - 1]).is_some() {
        Some(idx - 1)
    } else if idx > 1 && idx == len_l - 1 && tokens[idx - 1] == " " && hms(&tokens[idx - 2]).is_some() {
        Some(idx - 2)
    } else {
        None
    }
}

fn adjust_ampm(hour: i32, ampm: usize) -> i32 {
    if hour < 12 && ampm == 1 {
        hour + 12
    } else if hour == 12 && ampm == 0 {
        0
    } else {
        hour
    }
}

fn could_be_tzname(res: &Res, token: &str) -> bool {
    res.hour.is_some()
        && res.tzname.is_none()
        && res.tzoffset.is_none()
        && token.chars().count() <= 5
        && (token.chars().all(|c| c.is_ascii_uppercase()) || UTCZONE.contains(&token))
}

fn to_int(s: &str) -> PResult<i32> {
    match to_decimal(s) {
        Some(v) => Ok(v as i32),
        None => Err(format!("InvalidNumeric({:?})", s)),
    }
}

fn parse_numeric_token(tokens: &[String], idx0: usize, ymd: &mut Ymd, res: &mut Res) -> PResult<usize> {
    let mut idx = idx0;
    let value_repr = tokens[idx].clone();
    let value = match to_decimal(&value_repr) {
        Some(v) => v,
        None => return Err(format!("InvalidNumeric({:?})", value_repr)),
    };
    let len_li = value_repr.chars().count();
    let len_l = tokens.len();
    if ymd.vals.len() == 3
        && (len_li == 2 || len_li == 4)
        && res.hour.is_none()
        && (idx + 1 >= len_l || (tokens[idx + 1] != ":" && hms(&tokens[idx + 1]).is_none()))
    {
        let s = &value_repr;
        res.hour = Some(to_int(&s[..2])?);
        if len_li == 4 {
            res.minute = Some(to_int(&s[2..])?);
        }
    } else if len_li == 6 || (len_li > 6 && value_repr.find('.') == Some(6)) {
        let s = &value_repr;
        if ymd.vals.is_empty() && !value_repr.contains('.') {
            ymd.append(to_int(&s[..2])?, Some(&s[..2]), None)?;
            ymd.append(to_int(&s[2..4])?, Some(&s[2..4]), None)?;
            ymd.append(to_int(&s[4..])?, Some(&s[4..]), None)?;
        } else {
            res.hour = Some(to_int(&s[..2])?);
            res.minute = Some(to_int(&s[2..4])?);
            let (sec, ns) = parsems(&s[4..])?;
            res.second = Some(sec);
            res.nanosecond = Some(ns);
        }
    } else if len_li == 8 || len_li == 12 || len_li == 14 {
        let s = &value_repr;
        ymd.append(to_int(&s[..4])?, Some(&s[..4]), Some(Label::Y))?;
        ymd.append(to_int(&s[4..6])?, Some(&s[4..6]), None)?;
        ymd.append(to_int(&s[6..8])?, Some(&s[6..8]), None)?;
        if len_li > 8 {
            res.hour = Some(to_int(&s[8..10])?);
            res.minute = Some(to_int(&s[10..12])?);
            if len_li > 12 {
                res.second = Some(to_int(&s[12..])?);
            }
        }
    } else if let Some(hms_idx) = find_hms_idx(idx, tokens, true) {
        let (new_idx, h) = if hms_idx > idx {
            (hms_idx, hms(&tokens[hms_idx]).unwrap())
        } else {
            (idx, hms(&tokens[hms_idx]).unwrap() + 1)
        };
        idx = new_idx;
        if h == 0 {
            res.hour = Some(value as i32);
            if value % 1.0 != 0.0 {
                res.minute = Some((60.0 * (value % 1.0)) as i32);
            }
        } else if h == 1 {
            let (m, s) = parse_min_sec(value);
            res.minute = Some(m);
            if s.is_some() {
                res.second = s;
            }
        } else if h == 2 {
            let (s, ns) = parsems(&value_repr)?;
            res.second = Some(s);
            res.nanosecond = Some(ns);
        }
    } else if idx + 2 < len_l && tokens[idx + 1] == ":" {
        res.hour = Some(value as i32);
        let v2 = match to_decimal(&tokens[idx + 2]) {
            Some(v) => v,
            None => return Err(format!("InvalidNumeric({:?})", tokens[idx + 2])),
        };
        let (m, s) = parse_min_sec(v2);
        res.minute = Some(m);
        if s.is_some() {
            res.second = s;
        }
        if idx + 4 < len_l && tokens[idx + 3] == ":" {
            let (s, ns) = parsems(&tokens[idx + 4])?;
            res.second = Some(s);
            res.nanosecond = Some(ns);
            idx += 2;
        }
        idx += 2;
    } else if idx + 1 < len_l && (tokens[idx + 1] == "-" || tokens[idx + 1] == "/" || tokens[idx + 1] == ".") {
        let sep = tokens[idx + 1].clone();
        ymd.append(value as i32, Some(&value_repr), None)?;
        if idx + 2 < len_l && !jump(&tokens[idx + 2]) {
            if tokens[idx + 2].chars().all(|c| c.is_ascii_digit()) && !tokens[idx + 2].is_empty() {
                ymd.append(to_int(&tokens[idx + 2])?, Some(&tokens[idx + 2]), None)?;
            } else {
                match month(&tokens[idx + 2]) {
                    Some(m) => ymd.append(m as i32, None, Some(Label::M))?,
                    None => return Err("UnrecognizedFormat".to_string()),
                }
            }
            if idx + 3 < len_l && tokens[idx + 3] == sep {
                if idx + 4 >= len_l {
                    return Err("UnrecognizedFormat".to_string());
                }
                match month(&tokens[idx + 4]) {
                    Some(m) => ymd.append(m as i32, None, Some(Label::M))?,
                    None => ymd.append(to_int(&tokens[idx + 4])?, Some(&tokens[idx + 4]), None)?,
                }
                idx += 2;
            }
            idx += 1;
        }
        idx += 1;
    } else if idx + 1 >= len_l || jump(&tokens[idx + 1]) {
        if idx + 2 < len_l && ampm(&tokens[idx + 2]).is_some() {
            let hour = value as i32;
            res.hour = Some(adjust_ampm(hour, ampm(&tokens[idx + 2]).unwrap()));
            idx += 1;
        } else {
            ymd.append(value as i32, Some(&value_repr), None)?;
        }
        idx += 1;
    } else if ampm(&tokens[idx + 1]).is_some() && (0.0..24.0).contains(&value) {
        let hour = value as i32;
        res.hour = Some(adjust_ampm(hour, ampm(&tokens[idx + 1]).unwrap()));
        idx += 1;
    } else if ymd.could_be_day(value as i32) {
        ymd.append(value as i32, Some(&value_repr), None)?;
    } else {
        return Err("UnrecognizedFormat".to_string());
    }
    Ok(idx)
}

fn convert_year(year: i32, century_specified: bool) -> i32 {
    let now = Utc::now().naive_utc();
    let cur = now.year();
    let century = cur / 100 * 100;
    let mut y = year;
    if y < 100 && !century_specified {
        y += century;
        if y >= cur + 50 {
            y -= 100;
        } else if y < cur - 50 {
            y += 100;
        }
    }
    y
}

fn parse_res(timestr: &str) -> PResult<Res> {
    let mut res = Res::default();
    let mut l = timelex(timestr);
    let mut ymd = Ymd::default();
    let len_l = l.len();
    let mut i = 0;
    while i < len_l {
        let tok = l[i].clone();
        if to_decimal(&tok).is_some() {
            i = parse_numeric_token(&l, i, &mut ymd, &mut res)?;
        } else if let Some(w) = weekday(&tok) {
            res.weekday = Some(w);
        } else if let Some(m) = month(&tok) {
            ymd.append(m as i32, None, Some(Label::M))?;
            if i + 1 < len_l {
                if l[i + 1] == "-" || l[i + 1] == "/" {
                    let sep = l[i + 1].clone();
                    if i + 2 >= len_l {
                        return Err("UnrecognizedFormat".to_string());
                    }
                    ymd.append(to_int(&l[i + 2])?, Some(&l[i + 2]), None)?;
                    if i + 3 < len_l && l[i + 3] == sep {
                        if i + 4 >= len_l {
                            return Err("UnrecognizedFormat".to_string());
                        }
                        ymd.append(to_int(&l[i + 4])?, Some(&l[i + 4]), None)?;
                        i += 2;
                    }
                    i += 2;
                } else if i + 4 < len_l && l[i + 1] == " " && l[i + 3] == " " && pertain(&l[i + 2]) {
                    if l[i + 4].chars().all(|c| c.is_ascii_digit()) {
                        let v = to_int(&l[i + 4])?;
                        let y = convert_year(v, false);
                        ymd.append(y, Some(&y.to_string()), Some(Label::Y))?;
                    }
                    i += 4;
                }
            }
        } else if let Some(a) = ampm(&tok) {
            let valid = match res.hour {
                None => false,
                Some(h) => (0..=12).contains(&h),
            };
            if valid && res.ampm.is_none() {
                res.hour = Some(adjust_ampm(res.hour.unwrap(), a));
                res.ampm = Some(a);
            } else if valid {
                res.hour = Some(adjust_ampm(res.hour.unwrap(), a));
                res.ampm = Some(a);
            }
        } else if could_be_tzname(&res, &tok) {
            res.tzname = Some(tok.clone());
            res.tzoffset = None;
            if utczone(&tok) {
                res.tzoffset = Some(0);
            }
            if i + 1 < len_l && (l[i + 1] == "+" || l[i + 1] == "-") {
                l[i + 1] = if l[i + 1] == "+" { "-".to_string() } else { "+".to_string() };
                res.tzoffset = None;
                if utczone(&tok) {
                    res.tzname = None;
                }
            }
        } else if res.hour.is_some() && (tok == "+" || tok == "-") {
            let signal = if tok == "+" { 1 } else { -1 };
            if i + 1 >= len_l {
                return Err("UnrecognizedFormat".to_string());
            }
            let nxt = l[i + 1].clone();
            let len_li = nxt.chars().count();
            let (hour_offset, min_offset);
            if len_li == 4 {
                hour_offset = to_int(&nxt[..2])?;
                min_offset = to_int(&nxt[2..])?;
            } else if i + 2 < len_l && l[i + 2] == ":" {
                hour_offset = to_int(&nxt)?;
                if i + 3 >= len_l {
                    return Err("UnrecognizedFormat".to_string());
                }
                min_offset = to_int(&l[i + 3])?;
                i += 2;
            } else if len_li <= 2 {
                hour_offset = to_int(&nxt[..len_li.min(2)])?;
                min_offset = 0;
            } else {
                return Err("UnrecognizedFormat".to_string());
            }
            res.tzoffset = Some(signal * (hour_offset * 3600 + min_offset * 60));
            if i + 5 < len_l
                && jump(&l[i + 2])
                && l[i + 3] == "("
                && l[i + 5] == ")"
                && l[i + 4].chars().count() >= 3
                && could_be_tzname(&Res { hour: res.hour, ..Default::default() }, &l[i + 4])
            {
                res.tzname = Some(l[i + 4].clone());
                i += 4;
            }
            i += 1;
        } else if !jump(&tok) {
            return Err(format!("UnrecognizedToken({:?})", tok));
        }
        i += 1;
    }
    let (y, m, d) = ymd.resolve()?;
    res.century_specified = ymd.century_specified;
    res.year = y;
    res.month = m;
    res.day = d;
    // validate
    if let Some(y) = res.year {
        res.year = Some(convert_year(y, res.century_specified));
    }
    if (res.tzoffset == Some(0) && res.tzname.is_none()) || res.tzname.as_deref() == Some("Z") || res.tzname.as_deref() == Some("z") {
        res.tzname = Some("UTC".to_string());
        res.tzoffset = Some(0);
    } else if res.tzoffset.is_some() && res.tzoffset != Some(0) && res.tzname.as_deref().map(utczone).unwrap_or(false) {
        res.tzoffset = Some(0);
    }
    Ok(res)
}

pub fn parse(s: &str) -> Result<DateTime<Utc>, String> {
    let res = parse_res(s)?;
    if res.len() == 0 {
        return Err("NoDate".to_string());
    }
    let now = Utc::now().naive_utc();
    let default = NaiveDateTime::new(now.date(), NaiveTime::from_hms_opt(0, 0, 0).unwrap());
    let y = res.year.unwrap_or(default.year());
    let m = res.month.unwrap_or(default.month() as i32);
    let dim = days_in_month(y, m)?;
    let day = res.day.unwrap_or(default.day() as i32).min(dim);
    let mut d = NaiveDate::from_ymd_opt(y, m as u32, day as u32)
        .ok_or_else(|| "ImpossibleTimestamp(\"Invalid date range given\")".to_string())?;
    if let (Some(wd), None) = (res.weekday, res.day) {
        let cur = d.weekday().num_days_from_monday() as i64;
        let diff = (wd as i64 - cur).rem_euclid(7);
        d += chrono::TimeDelta::days(diff);
    }
    let hour = res.hour.unwrap_or(0);
    let minute = res.minute.unwrap_or(0);
    let second = res.second.unwrap_or(0);
    let nano = res.nanosecond.unwrap_or(0);
    let t = NaiveTime::from_hms_nano_opt(hour as u32, minute as u32, second as u32, nano as u32).ok_or_else(|| {
        if !(0..24).contains(&hour) {
            "ImpossibleTimestamp(\"Invalid hour\")".to_string()
        } else if !(0..60).contains(&minute) {
            "ImpossibleTimestamp(\"Invalid minute\")".to_string()
        } else if !(0..60).contains(&second) {
            "ImpossibleTimestamp(\"Invalid second\")".to_string()
        } else {
            "ImpossibleTimestamp(\"Invalid microsecond\")".to_string()
        }
    })?;
    // timezone handling (offset ignored)
    if res.tzoffset.is_none() {
        if let Some(name) = &res.tzname {
            if name != " " && name != "." && name != "-" {
                println!("tzname {} identified but not understood.", name);
            }
        }
    }
    Ok(NaiveDateTime::new(d, t).and_utc())
}
