// Date parsing modelled after the dateutil parser algorithm.
use chrono::{DateTime, Datelike, NaiveDate, NaiveDateTime, NaiveTime, Utc};

fn is_word(c: char) -> bool {
    c.is_alphabetic()
}
fn is_num(c: char) -> bool {
    c.is_numeric()
}
fn is_space(c: char) -> bool {
    c.is_whitespace()
}

pub fn timelex(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let mut pos = 0;
    let mut charstack: Vec<char> = vec![];
    let mut tokenstack: Vec<String> = vec![];
    let mut out = vec![];
    let mut eof = false;
    loop {
        if !tokenstack.is_empty() {
            out.push(tokenstack.remove(0));
            continue;
        }
        if eof && charstack.is_empty() {
            break;
        }
        let mut seenletters = false;
        let mut token: Option<String> = None;
        let mut state: Option<&str> = None;
        loop {
            let nextchar = if !charstack.is_empty() {
                charstack.remove(0)
            } else {
                if pos >= chars.len() {
                    eof = true;
                    break;
                }
                let c = chars[pos];
                pos += 1;
                if c == '\0' {
                    continue;
                }
                c
            };
            match state {
                None => {
                    token = Some(nextchar.to_string());
                    if is_word(nextchar) {
                        state = Some("a");
                    } else if is_num(nextchar) {
                        state = Some("0");
                    } else if is_space(nextchar) {
                        token = Some(" ".to_string());
                        break;
                    } else {
                        break;
                    }
                }
                Some("a") => {
                    seenletters = true;
                    let t = token.as_mut().unwrap();
                    if is_word(nextchar) {
                        t.push(nextchar);
                    } else if nextchar == '.' {
                        t.push(nextchar);
                        state = Some("a.");
                    } else {
                        charstack.push(nextchar);
                        break;
                    }
                }
                Some("0") => {
                    let t = token.as_mut().unwrap();
                    if is_num(nextchar) {
                        t.push(nextchar);
                    } else if nextchar == '.' || (nextchar == ',' && t.chars().count() >= 2) {
                        t.push(nextchar);
                        state = Some("0.");
                    } else {
                        charstack.push(nextchar);
                        break;
                    }
                }
                Some("a.") => {
                    seenletters = true;
                    let t = token.as_mut().unwrap();
                    if nextchar == '.' || is_word(nextchar) {
                        t.push(nextchar);
                    } else if is_num(nextchar) && t.ends_with('.') {
                        t.push(nextchar);
                        state = Some("0.");
                    } else {
                        charstack.push(nextchar);
                        break;
                    }
                }
                Some("0.") => {
                    let t = token.as_mut().unwrap();
                    if nextchar == '.' || is_num(nextchar) {
                        t.push(nextchar);
                    } else if is_word(nextchar) && t.ends_with('.') {
                        t.push(nextchar);
                        state = Some("a.");
                    } else {
                        charstack.push(nextchar);
                        break;
                    }
                }
                _ => break,
            }
        }
        let mut token = match token {
            Some(t) => t,
            None => {
                if eof && charstack.is_empty() {
                    break;
                }
                continue;
            }
        };
        if let Some(st) = state {
            if (st == "a." || st == "0.")
                && (seenletters || token.matches('.').count() > 1 || token.ends_with('.') || token.ends_with(','))
            {
                // split on [.,] keeping separators
                let mut parts: Vec<String> = vec![];
                let mut cur = String::new();
                for c in token.chars() {
                    if c == '.' || c == ',' {
                        parts.push(std::mem::take(&mut cur));
                        parts.push(c.to_string());
                    } else {
                        cur.push(c);
                    }
                }
                parts.push(cur);
                token = parts[0].clone();
                for p in parts.into_iter().skip(1) {
                    if !p.is_empty() {
                        tokenstack.push(p);
                    }
                }
            }
            if st == "0." && !token.contains('.') {
                token = token.replace(',', ".");
            }
        }
        out.push(token);
    }
    out
}

const JUMP: &[&str] = &[" ", ".", ",", ";", "-", "/", "'", "at", "on", "and", "ad", "m", "t", "of", "st", "nd", "rd", "th"];
const WEEKDAYS: &[&[&str]] = &[
    &["mon", "monday"],
    &["tue", "tuesday"],
    &["wed", "wednesday"],
    &["thu", "thursday"],
    &["fri", "friday"],
    &["sat", "saturday"],
    &["sun", "sunday"],
];
const MONTHS: &[&[&str]] = &[
    &["jan", "january"],
    &["feb", "february"],
    &["mar", "march"],
    &["apr", "april"],
    &["may", "may"],
    &["jun", "june"],
    &["jul", "july"],
    &["aug", "august"],
    &["sep", "sept", "september"],
    &["oct", "october"],
    &["nov", "november"],
    &["dec", "december"],
];
const HMS: &[&[&str]] = &[&["h", "hour", "hours"], &["m", "minute", "minutes"], &["s", "second", "seconds"]];
const AMPM: &[&[&str]] = &[&["am", "a"], &["pm", "p"]];
const UTCZONE: &[&str] = &["UTC", "GMT", "Z", "z"];
const PERTAIN: &[&str] = &["of"];

fn lookup(table: &[&[&str]], s: &str) -> Option<usize> {
    let l = s.to_lowercase();
    table.iter().position(|names| names.contains(&l.as_str()))
}
fn jump(s: &str) -> bool {
    JUMP.contains(&s.to_lowercase().as_str())
}
fn weekday(s: &str) -> Option<usize> {
    lookup(WEEKDAYS, s)
}
fn month(s: &str) -> Option<usize> {
    lookup(MONTHS, s).map(|m| m + 1)
}
fn hms(s: &str) -> Option<usize> {
    lookup(HMS, s)
}
fn ampm(s: &str) -> Option<usize> {
    lookup(AMPM, s)
}
fn pertain(s: &str) -> bool {
    PERTAIN.contains(&s.to_lowercase().as_str())
}
fn utczone(s: &str) -> bool {
    UTCZONE.contains(&s)
}

#[derive(Default, Debug)]
struct Res {
    year: Option<i32>,
    month: Option<i32>,
    day: Option<i32>,
    weekday: Option<usize>,
    hour: Option<i32>,
    minute: Option<i32>,
    second: Option<i32>,
    nanosecond: Option<i64>,
    tzname: Option<String>,
    tzoffset: Option<i32>,
    ampm: Option<usize>,
    century_specified: bool,
}

impl Res {
    fn len(&self) -> usize {
        let mut n = 0;
        if self.year.is_some() {
            n += 1
        }
        if self.month.is_some() {
            n += 1
        }
        if self.day.is_some() {
            n += 1
        }
        if self.weekday.is_some() {
            n += 1
        }
