#[derive(Clone, Copy)]
struct E { v: f64, g: u32, d: u32 }
fn inv(r: f64, e: f64) -> u32 { let i = (2.0 * e * r).floor() as u32; if i == 0 { 1 } else { i } }
#[derive(Clone, Copy, Debug)]
struct Var { err: f64, ends: u8, scan_le: bool, dmode: u8, cmode: u8, rstart: u32 }
struct C { var: Var, n: usize, s: Vec<E>, thr: usize, ins: usize }
