                for e in self.s.iter() { let c = if var.scan_le { e.v <= v } else { e.v < v }; if c { idx += 1; r += e.g } else { break } }
                let d = if idx == 0 || idx == self.s.len() { 0 } else { match var.dmode { 0 => inv(r as f64, var.err) - 1, 1 => inv(r as f64, var.err), 2 => (2.0*var.err*r as f64).floor() as u32, _ => inv(r as f64, var.err).saturating_sub(1) } };
                self.s.insert(idx, E{v,g:1,d});
            }
        }
        match var.cmode {
            0 => { self.ins = (self.ins + 1) % self.thr; if self.ins == 0 { self.compress(); } }
            1 => { if self.ins > self.thr { self.compress(); self.ins = 0; } self.ins = (self.ins + 1) % self.thr; }
            _ => { self.ins += 1; if self.ins >= self.thr { self.compress(); self.ins = 0; } }
        }
    }
    fn compress(&mut self) {
        if self.s.len() < 3 { return; }
        let mut mx = self.s.len() - 1; let mut idx = 0; let mut r: u32 = self.var.rstart;
        while idx < mx {
            let cg = self.s[idx].g; let nx = self.s[idx+1];
            if cg + nx.g + nx.d <= inv(r as f64, self.var.err) { self.s[idx] = E{v: nx.v, g: nx.g + cg, d: nx.d}; self.s.remove(idx+1); mx -= 1; } else { idx += 1; }
            r += 1;
        }
    }
    fn query(&self, q: f64) -> f64 {
        let s = self.s.len(); let mut r: u32 = 0; let nphi = q * self.n as f64;
        for i in 1..s { let p = self.s[i-1]; let c = self.s[i]; r += p.g; let lhs = (r + c.g + c.d) as f64; let rhs = nphi + inv(nphi, self.var.err) as f64 / 2.0; if lhs > rhs { return p.v; } }
        self.s[s-1].v
    }
}
fn main() {
