        let v: serde_json::Value = serde_json::from_str(j).unwrap();
        let o = v[0].as_object().unwrap();
        let qs = [("p1",0.01),("p5",0.05),("p10",0.1),("p25",0.25),("p50",0.5),("p75",0.75),("p90",0.9),("p95",0.95),("p99",0.99)];
        let expv: Vec<(f64,f64)> = qs.iter().map(|(k,q)| (*q, o[*k].as_f64().unwrap())).collect();
        let data: Vec<f64> = std::fs::read_to_string(format!("/tmp/ck/data/{}", f)).unwrap().lines().map(|l| l.parse().unwrap()).collect();
        cases.push((f.to_string(), data, expv));
    }
    let mut results: BTreeMap<usize, Vec<String>> = BTreeMap::new();
    for err in [0.001, 0.0005, 0.002, 0.005, 0.01] {
    for ends in 0..3u8 { for scan_le in [false, true] { for dmode in 0..3u8 { for cmode in 0..3u8 { for rstart in [0u32,1] {
        let var = Var{err, ends, scan_le, dmode, cmode, rstart};
        let mut score = 0; let mut bad = vec![];
        for (f, data, expv) in cases.iter() {
            let mut c = C::new(var);
            for x in data { c.insert(*x); }
            let mut ok = 0;
            for (q, e) in expv { let g = c.query(*q); if (g - e).abs() < 1e-9 { ok += 1; } }
            score += ok; if ok < 9 { bad.push(f.clone()); }
        }
        results.entry(score).or_default().push(format!("{:?} bad={:?}", var, bad));
    }}}}}}
    for (s, v) in results.iter().rev().take(3) { for x in v.iter().take(5) { println!("{} {}", s, x); } }
    println!("total {}", cases.len() * 9);
}
