enum Output {
    Rows(Vec<Record>),
    Table(Frame),
}

struct Runner {
    stages: Vec<Stage>,
    agg_pos: usize,
    display_sort: Option<(Vec<Expr>, bool)>,
    seg_bounds: Vec<(usize, usize)>,
    first_limit: Option<usize>,
    grouper: Option<Grouper>,
    first_buf: std::collections::VecDeque<Record>,
    collected: Vec<Record>,
}

impl Runner {
    fn new(stages: Vec<Stage>) -> Runner {
        let agg_pos = stages.iter().position(|s| matches!(s, Stage::Agg(..))).unwrap_or(stages.len());
        let mut display_sort: Option<(Vec<Expr>, bool)> = None;
        for st in stages[..agg_pos].iter() {
            if let Stage::Sort(e, d) = st {
                display_sort = Some((e.clone(), *d));
            }
        }
        let mut seg_bounds: Vec<(usize, usize)> = vec![];
        let mut s = 0;
        for i in 0..agg_pos {
            if let Stage::LimitLast(_) = stages[i] {
                seg_bounds.push((s, i));
                s = i + 1;
            }
        }
        seg_bounds.push((s, agg_pos));
        let first_limit = if seg_bounds.len() > 1 {
            match stages[seg_bounds[0].1] {
                Stage::LimitLast(n) => Some(n),
                _ => None,
            }
        } else {
            None
        };
        let grouper = match stages.get(agg_pos) {
            Some(Stage::Agg(aggs, by)) => Some(Grouper::new(aggs.clone(), by.clone())),
            _ => None,
        };
        Runner {
            stages,
            agg_pos,
            display_sort,
            seg_bounds,
            first_limit,
            grouper,
            first_buf: Default::default(),
            collected: vec![],
        }
    }

    fn streaming(&self) -> bool {
        self.seg_bounds.len() == 1 && self.display_sort.is_none() && self.agg_pos == self.stages.len()
    }

    fn feed(&mut self, line: &str) -> Option<Record> {
        let rec = Record { data: Default::default(), raw: Some(line.to_string()) };
        let (s0, e0) = self.seg_bounds[0];
        let rec = run_segment(&mut self.stages[s0..e0], rec)?;
        if self.streaming() {
            return Some(rec);
        }
        if let Some(n) = self.first_limit {
            self.first_buf.push_back(rec);
            if self.first_buf.len() > n {
                self.first_buf.pop_front();
            }
        } else if let Some(g) = self.grouper.as_mut() {
            g.add(&rec.data);
        } else {
            self.collected.push(rec);
        }
        None
    }

    fn compute(&self) -> Output {
        let mut stages = self.stages.clone();
        let mut grouper_tmp: Option<Grouper> = None;
        let mut collected: Vec<Record> = self.collected.clone();
        if self.seg_bounds.len() > 1 {
            let mut recs: Vec<Record> = self.first_buf.iter().cloned().collect();
            for (si, &(s, e)) in self.seg_bounds.iter().enumerate().skip(1) {
                let mut next = vec![];
                for r in recs.into_iter() {
