            (Some(g), _) => Some(g),
            (None, Some(g)) => Some(g),
            _ => None,
        };
        if let Some(g) = grouper {
            let mut frame = g.finish();
            for st in stages[self.agg_pos + 1..].iter_mut() {
                frame = match st {
                    Stage::Row(op) => {
                        if let RowOp::Limit { n, .. } = op {
                            let mut f = frame;
                            f.rows.truncate(*n as usize);
