    }
}

fn term_size() -> Option<(usize, usize)> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    const TIOCGWINSZ: u64 = 0x5413;
    let r = unsafe { ioctl(1, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if r == 0 && ws.ws_row > 0 && ws.ws_col > 0 {
        Some((ws.ws_row as usize, ws.ws_col as usize))
    } else {
        None
    }
}

fn render_live(output: &Output, mode: &OutputMode) -> String {
    let mut buf: Vec<u8> = vec![];
    match output {
        Output::Table(frame) => {
            let mut f = frame.clone();
            if let OutputMode::Legacy = mode {
                if let Some((rows, _)) = term_size() {
                    let max = rows.saturating_sub(3);
                    f.rows.truncate(max);
                }
            }
            let _ = render::render_frame(&f, mode, &mut buf);
        }
        Output::Rows(rows) => {
            let mut r = RowRenderer::new(mode.clone());
            for rec in rows.iter() {
                let s = r.render(rec);
                buf.extend_from_slice(s.as_bytes());
                buf.push(b'\n');
            }
        }
    }
    String::from_utf8_lossy(&buf).to_string()
}

fn run_live(mut runner: Runner, reader: Box<dyn BufRead + Send>, matcher: &Matcher, mode: &OutputMode, out: &mut dyn Write) {
    let (tx, rx) = std::sync::mpsc::channel::<String>();
    std::thread::spawn(move || {
        let mut reader = reader;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            buf.clear();
            match reader.read_until(b'\n', &mut buf) {
                Ok(0) => break,
                Ok(_) => {}
                Err(_) => break,
            }
            let line = String::from_utf8_lossy(&buf).trim_end().to_string();
            if tx.send(line).is_err() {
                break;
            }
        }
    });
    let interval = std::time::Duration::from_millis(50);
    let mut next = std::time::Instant::now() + interval;
    let mut last_lines = 0usize;
    let mut draw = |runner: &Runner, out: &mut dyn Write, last_lines: &mut usize| {
        let s = render_live(&runner.compute(), mode);
        let mut prefix = String::new();
        for _ in 0..*last_lines {
            prefix.push_str("\x1b[2K\x1b[1A");
        }
        let msgs = dtparse::take_pending();
        for m in msgs {
            prefix.push_str(&m);
            prefix.push('\n');
        }
        let _ = write!(out, "{}{}", prefix, s);
        let _ = out.flush();
        *last_lines = s.matches('\n').count();
    };
    loop {
        let now = std::time::Instant::now();
        let timeout = if next > now { next - now } else { std::time::Duration::from_millis(0) };
        match rx.recv_timeout(timeout) {
            Ok(line) => {
                if matches(matcher, &line) {
                    runner.feed(&line);
                }
            }
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
        }
        if std::time::Instant::now() >= next {
            draw(&runner, out, &mut last_lines);
            next = std::time::Instant::now() + interval;
        }
    }
    draw(&runner, out, &mut last_lines);
}

