pub fn assign(data: &mut Data, target: &Expr, v: Value) -> Result<(), String> {
    let (head, rest) = match target {
        Expr::Column { head, rest } => (head, rest),
        other => return Err(format!("Expected valid expr, found {}", expr_kind(other))),
    };
