                    if last {
                        o.insert(k.clone(), v);
                        return Ok(());
                    }
                    cur = match o.get_mut(k) {
                        Some(x) => x,
                        None => return Err(format!("No value for key \\"{}\\"", k)),
                    };
                }
            }
            PathSeg::Index(idx) => {
                if !matches!(cur, Value::Array(_)) {
                    return Err(format!("Expected array, found {}", cur));
                }
                if let Value::Array(a) = cur {
                    let len = a.len() as i64;
                    let j = if *idx < 0 { len + *idx } else { *idx };
                    if j < 0 || j >= len {
                        return Err(format!("Index {} out of range", idx));
                    }
                    if last {
                        a[j as usize] = v;
                        return Ok(());
                    }
                    cur = &mut a[j as usize];
                }
            }
        }
    }
    Ok(())
}

