type Row = (usize, Option<i64>);
fn cmpk(a: &Row, b: &Row, desc: bool, ea: u8) -> Ordering {
    match (a.1, b.1) {
        (Some(x), Some(y)) => { let o = x.cmp(&y); if desc { o.reverse() } else { o } }
        (None, Some(_)) => match ea { 0 => Ordering::Less, 1 => Ordering::Greater, 2 => Ordering::Equal, _ => Ordering::Less },
        (Some(_), None) => match ea { 0 => Ordering::Less, 1 => Ordering::Less, 2 => Ordering::Equal, _ => Ordering::Greater },
        (None, None) => match ea { 0 => Ordering::Less, 1 => Ordering::Less, 2 => Ordering::Equal, _ => Ordering::Less },
    }
}
fn run(input: &[Row], desc: bool, ea: u8, eb: u8, mode: u8) -> Vec<usize> {
    let mut st: Vec<Row> = vec![];
    for r in input {
        if mode == 0 { st.sort_by(|a, b| cmpk(a, b, desc, ea)); st.push(*r); }
        else { st.push(*r); st.sort_by(|a, b| cmpk(a, b, desc, ea)); }
    }
    st.sort_by(|a, b| { let o = cmpk(a, b, desc, eb); if o == Ordering::Equal && a.1.is_some() && b.1.is_some() { a.0.cmp(&b.0) } else { o } });
    st.iter().map(|r| r.0).collect()
}
fn main() {
    let cases: Vec<(Vec<Row>, bool, Vec<usize>)> = vec![
        (vec![(0,None),(1,Some(2)),(2,Some(1))], false, vec![0,2,1]),
        (vec![(0,Some(2)),(1,None),(2,Some(1)),(3,Some(0)),(4,None)], false, vec![3,2,0,1,4]),
        (vec![(0,Some(2)),(1,None),(2,Some(1)),(3,Some(0)),(4,None)], true, vec![0,2,3,1,4]),
        (vec![(0,Some(2)),(1,None),(2,None)], false, vec![1,0,2]),
        (vec![(0,None),(1,None),(2,None),(3,None),(4,None)], false, vec![3,1,0,2,4]),
        (vec![(0,None),(1,None),(2,None),(3,None),(4,None)], true, vec![3,1,0,2,4]),
    ];
    for ea in 0..4u8 { for eb in 0..4u8 { for mode in 0..2u8 {
        let mut ok = 0;
        let mut outs = vec![];
        for (inp, desc, exp) in cases.iter() { let got = run(inp, *desc, ea, eb, mode); if &got == exp { ok += 1; } outs.push(got); }
        println!("ea={} eb={} mode={} ok={}/{} {:?}", ea, eb, mode, ok, cases.len(), outs);
    }}}
}
