fn sorter_cmp(
    a: &(Vec<Option<Value>>, Data),
    b: &(Vec<Option<Value>>, Data),
    cols: &[String],
    desc: bool,
) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    for (x, y) in a.0.iter().zip(b.0.iter()) {
        match (x, y) {
            (Some(x), Some(y)) => {
                let o = x.total_cmp(y);
                if o != Ordering::Equal {
                    return if desc { o.reverse() } else { o };
                }
            }
            _ => return Ordering::Less,
        }
    }
    for c in cols {
        let va = a.1.get(c).unwrap_or(&Value::None);
        let vb = b.1.get(c).unwrap_or(&Value::None);
        let o = va.total_cmp(vb);
        if o != Ordering::Equal {
            return o;
        }
    }
    Ordering::Equal
}

/// Sorts records the way the sort operator does when it receives raw records:
/// the accumulated rows are re-sorted after every arriving row.
pub fn display_sort(recs: Vec<Record>, exprs: &[Expr], desc: bool) -> Frame {
    let mut columns: Vec<String> = vec![];
    let mut st: Vec<(Vec<Option<Value>>, Data)> = Vec::with_capacity(recs.len());
    let mut any_err = false;
    for r in recs.into_iter() {
        let keys: Vec<Option<Value>> = exprs.iter().map(|e| eval(e, &r.data).ok()).collect();
        let err = keys.iter().any(|k| k.is_none());
        for k in r.data.keys() {
            if !columns.contains(k) {
                columns.push(k.clone());
            }
        }
        if err && !any_err {
            any_err = true;
            let cols = columns.clone();
            st.sort_by(|a, b| sorter_cmp(a, b, &cols, desc));
        }
        st.push((keys, r.data));
        if any_err {
            let cols = columns.clone();
            st.sort_by(|a, b| sorter_cmp(a, b, &cols, desc));
        }
    }
    let cols = columns.clone();
    st.sort_by(|a, b| sorter_cmp(a, b, &cols, desc));
    Frame { columns, rows: st.into_iter().map(|(_, d)| d).collect() }
}
