new = """fn run_tty_rows(mut runner: Runner, reader: Box<dyn BufRead + Send>, matcher: &Matcher, renderer: &mut RowRenderer, out: &mut dyn Write) {
    let (tx, rx) = std::sync::mpsc::channel::<String>();
    std::thread::spawn(move || {
        let mut reader = reader;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            buf.clear();
            match reader.read_until(b'\\n', &mut buf) {
                Ok(0) => break,
                Ok(_) => {}
                Err(_) => break,
            }
            let line = String::from_utf8_lossy(&buf).trim_end().to_string();
            if tx.send(line).is_err() {
                break;
            }
        }
    });
    let interval = std::time::Duration::from_millis(50);
    let mut next = std::time::Instant::now() + interval;
    let mut pending = String::new();
    loop {
        let now = std::time::Instant::now();
        let timeout = if next > now { next - now } else { std::time::Duration::from_millis(0) };
        match rx.recv_timeout(timeout) {
            Ok(line) => {
                if matches(matcher, &line) {
                    let res = runner.feed(&line);
                    for msg in dtparse::take_pending() {
                        pending.push_str(&msg);
                        pending.push('\\n');
                    }
                    if let Some(rec) = res {
                        pending.push_str(&renderer.render(&rec));
                        pending.push('\\n');
                    }
                }
            }
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
        }
        if std::time::Instant::now() >= next {
            if !pending.is_empty() {
                if write!(out, "{}", pending).is_err() {
                    std::process::exit(0);
                }
                let _ = out.flush();
                pending.clear();
            }
            next = std::time::Instant::now() + interval;
        }
    }
    let _ = write!(out, "{}", pending);
}

